window.TAMAM_PRODUCTS = {"products":[{"key":"ruyalar","engine":"studio","kind":"app","frame":"phone","name":"Rüyalar Atlası","stage":"live","platforms":["iOS","Web"],"sectors":["lifestyle"],"tagline":{"en":"One dream, four interpretations.","tr":"Bir rüya, dört yorum."},"description":{"en":"AI dream interpretation through four windows — spiritual, Sufi, intuitive and psychological — with a personal dream journal, a symbol atlas of 30 symbols, a morning Waking Score and monthly pattern reports.","tr":"Manevi, tasavvufi, sezgisel ve psikolojik dört pencereden yapay zekâ destekli rüya tabiri; kişisel rüya günlüğü, 30 sembollük sözlük, sabah Uyanış Puanı ve aylık Örüntü raporları."},"user":{"en":"Adults 18–45 who journal, meditate or follow astrology; Turkish first, EN/FR/AR next.","tr":"Günlük tutan, meditasyon yapan ya da astrolojiyi takip eden 18–45 yaş yetişkinler; önce Türkçe."},"aiCore":{"en":"Streaming interpretation (Claude Opus) with mode-specific prompts, Haiku auto-tagging of symbols and emotions, Sonnet deep analysis, Atlas'a Sor follow-up chat, recurring-theme detection.","tr":"Pencereye özel promptlarla akan yorum (Claude Opus), sembol ve duygu etiketleme (Haiku), Derin Analiz ve Atlas'a Sor sohbeti (Sonnet), tekrar eden tema tespiti."},"money":{"en":"Freemium. Atlas Premium ₺179/month or ₺1,490/year via iyzico on the web (billing switch-on pending); free tier live today.","tr":"Freemium. Atlas Premium aylık ₺179 ya da yıllık ₺1.490, web üzerinden iyzico ile (ödeme açılışı bekleniyor); ücretsiz katman bugün canlı."},"edge":{"en":"Already live and shipping — the proof point for the studio's speed. Emotional daily use with a natural annual upsell.","tr":"Canlıda ve sürekli gelişiyor — stüdyonun hızının kanıtı. Duygusal günlük kullanım, doğal yıllık plan geçişi."},"brand":{"bg":"#0a0a0c","fg":"#f5f1e8","accent":"#d4af37","fontDisplay":"Cormorant Garamond","fontBody":"Cormorant Garamond","fontsCss2":["Cormorant+Garamond:ital,wght@0,400..700;1,400..600"],"modes":{"manevi":"#c44a4a","tasavvufi":"#4a9078","sezgisel":"#d68a55","psikolojik":"#5a82c4"}},"links":[{"label":"ruyalaratlasi.com","url":"https://www.ruyalaratlasi.com"}],"phase":2},{"key":"vizem","engine":"studio","kind":"web","frame":"phone","name":"Vizem","stage":"live","platforms":[{"en":"Web","tr":"Web"},{"en":"Agency portal","tr":"Acente portalı"}],"sectors":["travel"],"tagline":{"en":"Visa applications, scored and handled.","tr":"Vizenizi hızlı ve güvenli alın."},"description":{"en":"Türkiye's digital visa-application platform: an encrypted document vault, an AI readiness score out of 100 with plain-Turkish fixes for every gap, appointment tracking with operator booking, and a rejection-recovery service. Schengen, UK, US and Umrah.","tr":"Türkiye'nin dijital vize başvuru platformu: şifreli belge kasası, her eksik için Türkçe aksiyon öneren 100 üzerinden AI skoru, operatör rezervasyonlu randevu takibi, ret kurtarma hizmeti. Schengen, İngiltere, ABD ve Umre."},"user":{"en":"1.27M Schengen applications from Türkiye in 2025 (#2 worldwide), 14.6% refused; 13,000+ licensed travel agencies (TÜRSAB members) as the B2B channel.","tr":"2025'te Türkiye'den 1,27 milyon Schengen başvurusu (dünyada 2.), %14,6 ret; B2B kanal olarak 13.000+ lisanslı seyahat acentesi (TÜRSAB üyesi)."},"aiCore":{"en":"Document understanding and completeness checks (Supabase edge functions), 0–100 application score with prioritized actions, rejection-letter analysis and appeal drafting.","tr":"Belge anlama ve eksik kontrolü, 0–100 başvuru skoru ve öncelikli aksiyonlar, ret mektubu analizi ve itiraz taslağı."},"money":{"en":"Per application: Standard ₺999 · Concierge ₺2,999 · Premium ₺4,999 · Rejection recovery ₺1,590 · Red Line (72h) ₺1,999; agency plans from ₺7,990/month.","tr":"Başvuru başına: Standart ₺999 · Concierge ₺2.999 · Premium ₺4.999 · Ret Kurtarma ₺1.590 · Kırmızı Hat ₺1.999. Acente abonelikleri aylık ₺7.990'dan."},"edge":{"en":"e-Devlet identity verification kills appointment scalpers; scores the file before the consulate does — we found no Turkish competitor doing this (Sept 2026).","tr":"e-Devlet doğrulaması randevu karaborsasını bitirir; dosyayı konsolosluktan önce puanlar — bunu yapan bir Türk rakip bulamadık (Eylül 2026)."},"brand":{"bg":"#080C14","fg":"#E2E8F0","accent":"#0FC5B4","fontDisplay":"Syne","fontBody":"Instrument Sans","fontsCss2":["Syne:wght@700;800","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#0D1520","card":"#121C2B","gold":"#F4B942","red":"#F05252","green":"#22C55E","muted":"#6B7FA3"}},"links":[{"label":"vizem.co","url":"https://vizem.co"}],"phase":1},{"key":"fifty","engine":"studio","kind":"app","frame":"phone","name":"50-50","stage":"live","platforms":["iOS","Android","Web"],"sectors":["finance"],"tagline":{"en":"Split costs, skip the drama.","tr":"Ortak harcama, sıfır drama."},"description":{"en":"Tricount-style expense splitting for friends, flatmates and travel groups: add expenses in three taps (or snap the receipt), see who owes what, clear the debt with the fewest transfers and one-tap ₺ payment requests. Bank-initiated settlement follows once a licensed payment-institution partner is signed.","tr":"Arkadaşlar, ev arkadaşları ve gezi grupları için harcama bölüşme: üç dokunuşta harcama ekleyin (ya da fişin fotoğrafını çekin), kim kime ne borçlu görün, en az transferle ve tek dokunuşlu ₺ ödeme isteğiyle hesabı kapatın. Lisanslı bir ödeme kuruluşuyla anlaşma imzalanınca banka hesabından doğrudan ödeme de gelecek."},"user":{"en":"Travel groups, flatmates, couples; Türkiye first, then Azerbaijan and MENA.","tr":"Gezi grupları, ev arkadaşları, çiftler; önce Türkiye, sonra Azerbaycan ve MENA."},"aiCore":{"en":"Receipt OCR and smart categorization; natural-language expense entry ('akşam yemeği 1.200, Ayşe ve Can ile böl').","tr":"Fiş OCR ve akıllı kategori; doğal dille harcama girişi ('akşam yemeği 1.200, Ayşe ve Can ile böl')."},"money":{"en":"Free splitting; Pro $2.99/month (groups, exports, multi-currency); settlement fee via a licensed payment-institution partner later.","tr":"Bölüşme ücretsiz; Pro aylık $2,99 (gruplar, dışa aktarım, çoklu para birimi); ileride lisanslı ödeme kuruluşu ortağıyla ödeme komisyonu."},"edge":{"en":"Every Turkish split feature settles inside its own wallet (Papara, Tosla, FUPS) or does not settle at all (Splital, Payla). Nobody settles bank-to-bank from the user's own account via FAST — that is the gap.","tr":"Türkiye'deki her bölüşme özelliği ya kendi cüzdanında kapatıyor (Papara, Tosla, FUPS) ya da hiç kapatmıyor (Splital, Payla). Kimse kullanıcının kendi hesabından FAST ile bankadan bankaya kapatmıyor — boşluk bu."},"brand":{"bg":"#F4F0E7","fg":"#171714","accent":"#C8F45A","fontDisplay":"Space Grotesk","fontBody":"Instrument Sans","fontsCss2":["Space+Grotesk:wght@500;700","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#FBFAF6","coral":"#FF7A63","blue":"#788EFF","red":"#BD3D2B"}},"links":[],"phase":2},{"key":"unfold","engine":"studio","kind":"app","frame":"phone","name":"Unfold","stage":"live","platforms":["iOS","Android"],"sectors":["lifestyle"],"tagline":{"en":"Your saved world, worth coming back to.","tr":"Kaydettiğiniz her şey, tek sakin yerde."},"description":{"en":"A home for everything you saved and never re-read: X bookmarks, Instagram and TikTok saves, screenshots and notes — imported, classified by Claude with your consent, searchable, and resurfaced when you need it.","tr":"Kaydedip bir daha açmadığınız her şeyin evi: X yer imleri, Instagram ve TikTok kayıtları, ekran görüntüleri ve notlar — içe aktarılır, izninizle Claude sınıflandırır, aranabilir hâle gelir ve zamanı gelince önünüze çıkar."},"user":{"en":"Heavy social users 18–35 who hoard saved posts; creators and researchers as Pro.","tr":"Kaydettiği gönderileri biriktiren 18–35 yaş yoğun sosyal medya kullanıcıları; Pro için içerik üreticileri ve araştırmacılar."},"aiCore":{"en":"Auto-tagging and clustering (text + vision), weekly 'unfold' digest, natural-language recall ('that pasta recipe from May').","tr":"Otomatik etiketleme ve kümeleme (metin + görsel), haftalık 'unfold' özeti, doğal dille hatırlama."},"money":{"en":"Free for a limited number of items; $3.99/month unlimited + digests; Pro for creators.","tr":"Sınırlı sayıda öğe ücretsiz; aylık $3,99 sınırsız + özetler; üreticiler için Pro."},"edge":{"en":"Nobody owns the 'saved' layer across platforms; the job is recall, not storage. Built on share-sheet and exports, not scraping. Working name — a trademark check against Squarespace's Unfold is pending.","tr":"Platformlar arası 'kaydedilenler' katmanı kimsede yok; iş depolama değil hatırlama. Paylaşım menüsü ve dışa aktarımlarla, kazıma yok. Çalışma adı — Squarespace'in Unfold'una karşı marka taraması bekliyor."},"brand":{"bg":"#f6f5ef","fg":"#223b33","accent":"#f6d878","fontDisplay":"Instrument Sans","fontBody":"Instrument Sans","fontsCss2":["Instrument+Sans:wght@400;500;600;700"],"extra":{"muted":"#68756e","line":"#e3e7df","button":"#edf0e9"}},"links":[],"phase":1},{"key":"yilan","engine":"studio","kind":"web","frame":"phone","name":{"en":"Kulis","tr":"Kulis"},"stage":"beta","platforms":["Web","App"],"sectors":["media"],"tagline":{"en":"Society, screen and influencers, verified.","tr":"Sosyete, ekran ve fenomenler — doğrulanmış."},"description":{"en":"A society, TV and influencer news app: who was where, what is on screen tonight and what creators are talking about. Every story is sourced and verified, summarised in 30 seconds, filed under its desk (society, screen, influencers, red carpet, music) and shareable in one tap. In beta with test users.","tr":"Sosyete, televizyon ve fenomen haberleri uygulaması: kim nerede, bu akşam ekranda ne var, içerik üreticileri ne konuşuyor. Her haber kaynaklı ve doğrulanmış, 30 saniyede özetlenmiş, masasına göre ayrılmış (sosyete, ekran, fenomen, kırmızı halı, müzik) ve tek dokunuşla paylaşılabilir. Test kullanıcılarıyla betada."},"user":{"en":"18–40 Turkish audience that follows society news, TV series and influencers on Instagram and TikTok but wants it fast and sourced.","tr":"Sosyete haberlerini, dizileri ve fenomenleri Instagram ve TikTok'ta takip eden ama hızlı ve kaynaklı isteyen 18–40 yaş Türk kitle."},"aiCore":{"en":"Automated content pipeline: source ingestion → verification → summary → headline variants → social cards. Shares the pipeline with The Istanbul Times.","tr":"Otomatik içerik hattı: kaynak toplama → doğrulama → özet → başlık varyantları → sosyal kartlar. The Istanbul Times ile aynı hat."},"money":{"en":"Programmatic and native ads, sponsored desks and creator partnerships; a light $2.99 premium for ad-free reading and early alerts.","tr":"Programatik ve native reklam, sponsorlu masalar ve içerik üreticisi iş birlikleri; reklamsız okuma ve erken uyarı için $2,99 hafif premium."},"edge":{"en":"Volume play: the cheapest audience in the portfolio, the cross-promotion engine for every other app and a natural home for creator and TV brand partnerships. The name means backstage — where society, screen and creator news really starts. A named editor owns publication and corrections.","tr":"Kitle işi: portföyün en ucuz kitlesi, diğer tüm uygulamaların çapraz tanıtım motoru ve içerik üreticisi ile TV marka iş birlikleri için doğal bir yer. Adı kulisten geliyor: sosyete, ekran ve fenomen haberi orada başlar. Yayından ve düzeltmelerden adı belli bir editör sorumlu."},"brand":{"bg":"#14080F","fg":"#FBEFF4","accent":"#FF2D6F","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,500..800","Instrument+Sans:wght@400;500;600"],"extra":{"velvet":"#3A0F25","gold":"#F5C451"}},"links":[],"slug":"kulis"},{"key":"gunaydin","engine":"studio","kind":"web","frame":"phone","name":"The Istanbul Times","stage":"live","platforms":["Web","iOS"],"sectors":["media"],"tagline":{"en":"From the Bosphorus to the world.","tr":"Boğaz’dan dünyaya."},"description":{"en":"A bilingual Istanbul morning newspaper and companion app at Live I: sourced stories, The Morning Five, a city desk and commute figures, F.I.T. markets, M.I.T. culture and media, Günaydun humour, email briefs and listen-to-story audio. The editor approves each edition. A first sample edition and the web and app screens are built; the public release is still being prepared.","tr":"Canlı I aşamasındaki iki dilli İstanbul gazetesi ve mobil uygulaması: kaynaklı haberler, Sabahın Beşi, şehir ve ulaşım, F.I.T. piyasaları, M.I.T. kültür ve medya, Günaydun mizah sayfası, e-posta bültenleri ve sesli okuma. Her baskıyı editör onaylıyor. İlk örnek baskı ve web ile uygulama ekranları hazır; genel yayın hazırlığı sürüyor."},"user":{"en":"Istanbul readers who want a sourced morning paper, city information and concise daily briefs.","tr":"Kaynaklı bir sabah gazetesi, şehir bilgisi ve kısa günlük bülten isteyen İstanbullu okurlar."},"aiCore":{"en":"Newsroom pipeline groups source feeds, drafts bilingual stories and checks figures, names and attribution; an editor reviews publication. Real model and email delivery still need live testing.","tr":"Haber masası kaynak akışlarını kümeliyor, iki dilde taslak hazırlıyor, sayı, isim ve atıfları kontrol ediyor; yayını editör onaylıyor. Gerçek model ve e-posta teslimatı canlı ortamda henüz sınanacak."},"money":{"en":"Membership and sponsorship are planned; payments are not connected.","tr":"Üyelik ve sponsorluk planlanıyor; ödeme bağlantısı henüz yok."},"edge":{"en":"One editorial system serves the paper, phone app and briefs. The first sourced sample edition is ready; public distribution remains a launch step.","tr":"Tek editoryal sistem web gazetesini, telefon uygulamasını ve bültenleri besliyor. Kaynaklı ilk örnek baskı hazır; genel dağıtım yayın aşamasında."},"brand":{"bg":"#F4EFE6","fg":"#161616","accent":"#9B1C1C","fontDisplay":"Playfair Display","fontBody":"Newsreader","fontsCss2":["Playfair+Display:wght@700;800;900","Newsreader:wght@400;600","Libre+Franklin:wght@400;600"],"extra":{"paper":"#F4EFE6","ink":"#161616","rule":"#B9AE9C","red":"#9B1C1C"}},"links":[],"phase":1},{"key":"kivo","engine":"studio","kind":"app","frame":"phone","name":"Kapi","stage":"live","platforms":["iOS","Android"],"sectors":["kids"],"tagline":{"en":"Play, learn and grow in Turkish, ages 2–12.","tr":"2–12 yaş için Türkçe oyun, öğrenme ve gelişim."},"description":{"en":"A Turkish, ad-free learning app for ages 2–12 with Kapi the capybara: 38 playable games in six areas—discovery, geography, numbers, logic, language and emotions. Age-matched rounds have spoken instructions and no penalty for mistakes. The parent panel reports actual play and can set a daily limit. The app is complete and tested for a first build, but is not yet in the stores.","tr":"2–12 yaş için Türkçe, reklamsız öğrenme uygulaması. Rehber kapibara Kapi ile keşif, coğrafya, sayılar, mantık, dil ve duygular alanlarında yaşa göre açılan 38 oynanabilir oyun var. Sesli yönergeler ve hataya ceza vermeyen turlar, gerçek oyun verilerini gösteren ebeveyn paneli ve günlük süre sınırı hazır. İlk sürüm test edildi; mağazalarda henüz yayımlanmadı."},"user":{"en":"Families in Türkiye with children aged 2–12 who want screen time that teaches, in Turkish and without ads.","tr":"Ekran süresinin öğretici, Türkçe ve reklamsız olmasını isteyen, 2–12 yaş çocuğu olan aileler."},"aiCore":{"en":"Age-matched games and spoken prompts run on the device. Draft stories require educator approval before appearing in a store build.","tr":"Yaşa göre oyunlar ve sesli yönergeler cihazda çalışır. Taslak hikâyeler mağaza sürümünde görünmeden önce eğitim uzmanı onayı ister."},"money":{"en":"Free and ad-free; no purchases or accounts in v1.","tr":"Ücretsiz ve reklamsız; ilk sürümde satın alma veya hesap yok."},"edge":{"en":"An offline Turkish game collection for ages 2–12 with a real parent panel and a memorable capybara guide.","tr":"2–12 yaş için çevrimdışı Türkçe oyunlar, gerçek verili ebeveyn paneli ve kapibara rehber."},"brand":{"bg":"#FFF7E6","fg":"#2B2440","accent":"#4DB86A","fontDisplay":"Baloo 2","fontBody":"Nunito","fontsCss2":["Baloo+2:wght@600;700;800","Nunito:wght@600;700;800"],"extra":{"salmon":"#F2A28F","yellow":"#F8D45D","violet":"#B2A7F2","green":"#A3DBA6"}},"links":[],"phase":2,"slug":"kapi"},{"key":"pati","engine":"studio","kind":"app","frame":"phone","name":"Pati","stage":"idea","platforms":["iOS","Android"],"sectors":["health","lifestyle"],"tagline":{"en":"An AI care companion for cat and dog owners.","tr":"Kedi ve köpek sahipleri için yapay zekâ bakım arkadaşı."},"description":{"en":"Photo-based symptom triage with safe escalation to vets, breed-aware food and portion guidance, training plans, vaccination and vet log — for two of the largest audiences on earth: cat and dog owners.","tr":"Fotoğrafla semptom ön değerlendirmesi ve veterinere güvenli yönlendirme, ırka göre mama ve porsiyon önerisi, eğitim planları, aşı ve veteriner defteri."},"user":{"en":"Cat and dog owners; Türkiye launch, then EN/ES/DE.","tr":"Kedi ve köpek sahipleri; önce Türkiye, sonra EN/ES/DE."},"aiCore":{"en":"Vision triage with escalation rules; breed-aware plans; reminders as an agent.","tr":"Görsel ön değerlendirme ve yönlendirme kuralları; ırka göre planlar; ajan olarak hatırlatmalar."},"money":{"en":"$4.99/month; affiliate on food and insurance; vet-clinic partnerships.","tr":"Aylık $4,99; mama ve sigorta satış ortaklığı; veteriner klinik ortaklıkları."},"edge":{"en":"Global pet apps are fragmented by function; one warm companion that does all four can travel globally from day one. Guidance only — emergencies always go to a vet.","tr":"Küresel evcil hayvan uygulamaları işleve göre parçalı; dördünü yapan sıcak bir arkadaş ilk günden küresel pazara açılabilir. Acil durum her zaman veterinere."},"brand":{"bg":"#FBF6EF","fg":"#3B2F2A","accent":"#E07A3F","fontDisplay":"Bricolage Grotesque","fontBody":"Nunito","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,500..800","Nunito:wght@500;700"],"extra":{"sage":"#8FB89A","cocoa":"#6B4E3D"}},"links":[]},{"key":"kese","engine":"studio","kind":"app","frame":"phone","name":"Kese","stage":"idea","platforms":["iOS","Web"],"sectors":["finance"],"tagline":{"en":"An inflation-aware money copilot for Türkiye.","tr":"Türkiye için enflasyona duyarlı para yardımcısı."},"description":{"en":"One view of TL, FX and gold across banks, spending insights from open banking, cash-flow forecasts and plain-Turkish answers to 'what if'. Connected to 50-50 for shared expenses.","tr":"Bankalar arası TL, döviz ve altının tek görünümü, açık bankacılıkla harcama içgörüleri, nakit akışı tahmini ve 'ya şöyle olursa' sorularına sade Türkçe yanıt. Ortak harcamalar için 50-50 ile bağlantılı."},"user":{"en":"Urban 25–45 earners juggling TL/USD/gold; later SMEs.","tr":"TL/USD/altın arasında denge kuran 25–45 yaş şehirli çalışanlar; sonra KOBİ'ler."},"aiCore":{"en":"Bank-statement understanding, cash-flow forecasting, what-if simulations. Information and tooling only, no advice claims.","tr":"Ekstre anlama, nakit akışı tahmini, senaryo simülasyonları. Yalnızca bilgi ve araç; yatırım tavsiyesi değildir."},"money":{"en":"$5.99/month; affiliate on savings/insurance; B2B2C with a bank or brokerage.","tr":"Aylık $5,99; tasarruf/sigorta satış ortaklığı; banka ya da aracı kurumla B2B2C."},"edge":{"en":"Turkish money apps are wallets or brokers; nobody explains your money across banks in plain Turkish.","tr":"Türkiye'deki para uygulamaları ya cüzdan ya aracı kurum; paranızı bankalar arasında sade Türkçeyle anlatan yok."},"brand":{"bg":"#0F1A17","fg":"#EAF2EC","accent":"#5CE0B8","fontDisplay":"IBM Plex Sans","fontBody":"IBM Plex Sans","fontsCss2":["IBM+Plex+Sans:wght@400;500;600;700","IBM+Plex+Mono:wght@400;500"],"extra":{"gold":"#E3B34C","usd":"#8FB3FF","danger":"#FF7B6B"}},"links":[]},{"key":"venturi","engine":"studio","kind":"web","frame":"browser","name":"Venturi","stage":"live","platforms":["Web"],"sectors":["finance"],"tagline":{"en":"Where Turkish VCs, angels and startups meet.","tr":"Türkiye'de VC'lerin, melek yatırımcıların ve girişimlerin buluştuğu yer."},"description":{"en":"Verified startup profiles (metrics pulled read-only from Stripe/GA4/app stores), machine-readable investor theses with an explainable fit score, deal rooms with view analytics, a grants directory, jobs and an AI copilot that drafts intro memos.","tr":"Doğrulanmış girişim profilleri, makine tarafından okunabilir yatırımcı tezleri ve açıklanabilir uyum skoru, görüntüleme analitikli veri odaları, hibe rehberi, iş ilanları ve tanışma notu yazan yapay zekâ yardımcısı."},"user":{"en":"Founders, angels, VC analysts and holdings' corporate-venture teams; TR first, then Balkans/GCC.","tr":"Kurucular, melek yatırımcılar, VC analistleri ve holdinglerin kurumsal girişim ekipleri; önce TR."},"aiCore":{"en":"Startup one-pager generation, investor matching (fit score v0: sector 40 · stage 20 · geo 15 · check-size 15 · traction 10), OSINT-lite background checks via the OSINT Agent.","tr":"Girişim özeti üretimi, yatırımcı eşleştirme (uyum skoru), OSINT Ajanı ile hafif arka plan kontrolü."},"money":{"en":"Free for founders; Pro $19.99/month for investors (deal alerts, exports); sponsored events and job board.","tr":"Kuruculara ücretsiz; yatırımcılara aylık $19,99 Pro; sponsorlu etkinlikler ve iş ilanı panosu."},"edge":{"en":"Direct line to the enterprise beachhead: the same investors and holdings are Engine 2 buyers.","tr":"Kurumsal pazara doğrudan kapı: aynı yatırımcılar ve holdingler 2. motorun alıcıları."},"brand":{"bg":"#F6F8FB","fg":"#1B2A41","accent":"#C08B2F","fontDisplay":"Playfair Display","fontBody":"Instrument Sans","fontsCss2":["Playfair+Display:wght@600;700;800","Instrument+Sans:wght@400;500;600"],"extra":{"navy":"#0B2545","navy2":"#13315C","goldb":"#D9A441","mist":"#EDF2F8","green":"#17784A","amber":"#95670F"}},"links":[],"phase":2},{"key":"prive","engine":"studio","kind":"web","frame":"browser","name":"Privé Travel · Alfred","stage":"build","platforms":[{"en":"Web","tr":"Web"},{"en":"iOS next","tr":"sırada iOS"}],"sectors":["travel"],"tagline":{"en":"Travel, perfectly arranged.","tr":"Kusursuz düzenlenmiş seyahat."},"description":{"en":"A curated, AI-native private travel service for affluent families, executives and family offices. Tell Alfred where you want to go and receive complete, arranged journeys — villas, flights, private aviation, transfers, dining and 24/7 concierge. 13 destinations, membership by invitation.","tr":"Varlıklı aileler, yöneticiler ve aile ofisleri için küratörlü, yapay zekâ tabanlı özel seyahat servisi. Alfred'e nereye gitmek istediğinizi söyleyin, eksiksiz düzenlenmiş yolculuklar alın. 13 destinasyon, davetle üyelik."},"user":{"en":"Affluent families and executives, Istanbul first; partner villas, chalets and operators.","tr":"Varlıklı aileler ve yöneticiler, önce İstanbul; partner villalar, dağ evleri ve operatörler."},"aiCore":{"en":"Alfred turns one natural-language request into four fully-costed journey options (Best Overall / Best Location / Most Private / Best Value) and hands off to a named operations owner.","tr":"Alfred tek bir doğal dil isteğini maliyeti tam hesaplanmış dört yolculuk seçeneğine (En İyi / En İyi Konum / En Özel / En Uygun) çevirir ve adı belli bir operasyon sorumlusuna devreder."},"money":{"en":"Planned: membership from about $1,000/year (Alfred · Alfred Private · Alfred Office tiers) plus commission or net-rate on partner inventory. Prices on the site are illustrative.","tr":"Planlanan: yıllık yaklaşık 1.000 dolardan başlayan üyelik (Alfred · Alfred Private · Alfred Office) ve partner envanterinde komisyon ya da net oran. Sitedeki fiyatlar temsilî."},"edge":{"en":"Nothing is labelled confirmed unless a partner confirmed it; no discounts, no urgency timers — a private-bank tone in travel.","tr":"Partner onaylamadan hiçbir şey 'onaylandı' denmez; indirim ve aciliyet sayacı yok — seyahatte özel banka tonu."},"brand":{"bg":"#08080a","fg":"#efe8d8","accent":"#c9a961","fontDisplay":"Cormorant Garamond","fontBody":"Instrument Sans","fontsCss2":["Cormorant+Garamond:ital,wght@0,400..600;1,400","Instrument+Sans:wght@400;500"],"extra":{"obsidian800":"#131318","obsidian600":"#23232c","gold300":"#e6cf8e","ivory300":"#cfc7b5"}},"links":[{"label":"privetravel.vercel.app","url":"https://privetravel.vercel.app"}]},{"key":"hatir","engine":"studio","kind":"app","frame":"call","name":{"en":"Selam (working name)","tr":"Selam (çalışma adı)"},"stage":"idea","platforms":[{"en":"Any phone (voice call)","tr":"Her telefon (sesli arama)"},{"en":"Family app","tr":"Aile uygulaması"}],"tagline":{"en":"A daily hello on any phone: company, reminders and a scam shield.","tr":"Her telefona her gün bir selam: sohbet, hatırlatma, dolandırıcılığa karşı kalkan."},"description":{"en":"An AI voice companion for older adults that calls every day on the phone they already have — landline or basic mobile, no app. It says it is an AI, asks how they are, remembers what they shared, reminds them of medicines and appointments, passes regards to and from the family, helps them spot phone scams and points to 112 in an emergency. The older person owns the account, consents in their own voice and decides what the family sees; transcripts stay with them. In Turkish the daily call keeps its old name, 'hâl hatır araması'. Not a medical or emergency service. Municipalities, home-care providers, care homes and insurers later.","tr":"Büyüklerimizi her gün, ellerindeki telefondan — sabit hat ya da tuşlu telefon, uygulama yok — arayan yapay zekâ ses arkadaşı. Yapay zekâ olduğunu söyler, hâl hatır sorar, anlattıklarını hatırlar, ilaç ve randevuyu hatırlatır, aileden gelen ve aileye giden selamı iletir, telefon dolandırıcılığını fark etmelerine yardım eder ve acil durumda 112'ye yönlendirir. Hesap büyüğümüzündür; onayını kendi sesiyle verir, ailenin neyi göreceğine o karar verir; görüşme dökümü onda kalır. Günlük aramanın adı Türkçede yine 'hâl hatır araması'. Tıbbi ya da acil durum hizmeti değildir. Sonra belediyeler, evde bakım firmaları, bakımevleri ve sigortacılar."},"user":{"en":"Older adults, especially those living alone, and the family circle they invite (often children in another city or abroad); later municipal social services, home-care providers, care homes and insurers.","tr":"Büyüklerimiz, özellikle yalnız yaşayanlar, ve onların davet ettiği aile halkası (çoğu zaman başka şehirde ya da yurt dışında yaşayan çocuklar); sonra belediye sosyal hizmetleri, evde bakım firmaları, bakımevleri ve sigortacılar."},"aiCore":{"en":"Turkish voice agent on a Turkish carrier line, consented memory of past calls, wellbeing from the person's own words against their own baseline, scam-script detection in conversation, rule-based escalation to family or 112 guidance (never diagnosis).","tr":"Türk operatör hattında Türkçe ses ajanı, rızaya dayalı görüşme hafızası, kişinin kendi sözlerinden ve kendi olağanına göre esenlik, sohbet içinde dolandırıcılık senaryosu tespiti, aileye ya da 112 yönlendirmesine kurallı geçiş (asla teşhis değil)."},"money":{"en":"A family subscription that anyone in the circle can pay, priced after the Turkish-carrier voice-cost check; per-person licences for municipalities, home-care providers, care homes and insurers. Never ads, data sales or sponsored health messages in calls.","tr":"Aile halkasından herkesin ödeyebileceği aile aboneliği; fiyat, Türk operatör ses maliyeti kontrolünden sonra belirlenir; belediyeler, evde bakım firmaları, bakımevleri ve sigortacılar için kişi başı lisans. Aramalarda asla reklam, veri satışı ya da sponsorlu sağlık mesajı yok."},"edge":{"en":"In Türkiye, Viva Smart Care sells sensors plus a call centre and Albert Health an in-app voice assistant; neither markets a proactive outbound AI phone call as its core product (Sept 2026 review). The format is proven abroad (Naver's CLOVA CareCall in Korean municipalities, Japan Post's daily call, Joy Calls in the US) but not in Turkish, and scam-call protection was not among the features listed in the sources reviewed. Launches month 18 after the voice stack is proven inside Engine 2.","tr":"Türkiye'de Viva Smart Care sensör ve çağrı merkezi, Albert Health uygulama içi ses asistanı sunuyor; hiçbiri kendiliğinden arayan bir yapay zekâ çağrısını ana ürün olarak pazarlamıyor (Eylül 2026 incelemesi). Model yurt dışında kanıtlandı (Kore belediyelerinde Naver CLOVA CareCall, Japonya Postası'nın günlük araması, ABD'de Joy Calls) ama Türkçe değil; incelenen kaynaklarda dolandırıcılık kalkanı özellik olarak yer almıyor. Ses altyapısı 2. motorda kanıtlandıktan sonra, 18. ayda."},"brand":{"bg":"#F7F3EA","fg":"#2E2A24","accent":"#5B8C6F","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,400..700","Instrument+Sans:wght@400;500;600"],"extra":{"call":"#1F7A4D","warm":"#D9A066","alert":"#E0A43A","alertInk":"#7A4E08","alertBg":"#FBEFD6"}},"links":[],"slug":"selam","sectors":["health"]},{"key":"disaster","engine":"studio","kind":"web","frame":"browser","name":"Disaster Sim","stage":"live","platforms":["Web"],"sectors":["gaming","kids","security"],"tagline":{"en":"What if it happened here?","tr":"Burada olsaydı ne olurdu?"},"description":{"en":"Ten interactive disaster simulators on one dark map: earthquakes, wildfires, storms, volcanoes, nuclear, industrial accidents, refugee flows and pandemics. Replays 17 real events against recorded tolls using the real hourly weather of that week (ERA5), USGS quakes, RainViewer radar. No backend.","tr":"Tek karanlık haritada on etkileşimli afet simülatörü: deprem, orman yangını, fırtına, volkan, nükleer, sanayi kazası, göç ve pandemi. 17 gerçek olayı o haftanın gerçek saatlik hava verisiyle (ERA5), USGS depremleri ve RainViewer radarıyla kayıtlı kayıplara karşı yeniden oynatır. Sunucusuz."},"user":{"en":"Municipal and insurer training (B2B angle); a viral web toy for traffic.","tr":"Belediye ve sigortacı eğitimi (B2B açısı); trafik için viral web oyuncağı."},"aiCore":{"en":"Physically grounded models (GMPE/PAGER, Rothermel-style fire automaton, SEIR, Lanchester) rather than an LLM; AI-assisted scenario narration later.","tr":"LLM değil fiziksel modeller (GMPE/PAGER, Rothermel yangın otomatı, SEIR, Lanchester); sonra yapay zekâ destekli senaryo anlatımı."},"money":{"en":"Decision gate month 6: keep as a web toy for traffic, or pitch to one insurer.","tr":"6. ay karar kapısı: trafik için web oyuncağı mı, bir sigortacıya teklif mi."},"edge":{"en":"The Kahramanmaraş 2023 replay shows the model's estimate beside the recorded toll inside the app — the credibility test for the training angle.","tr":"Kahramanmaraş 2023 tekrarı, modelin tahminini kayıtlı kaybın yanında uygulamanın içinde gösterir — eğitim açısının güvenilirlik testi."},"brand":{"bg":"#0b0f14","fg":"#e6edf3","accent":"#ffb020","fontDisplay":"Instrument Sans","fontBody":"Instrument Sans","fontsCss2":["Instrument+Sans:wght@400;500;600;700","JetBrains+Mono:wght@400;500"],"extra":{"panel":"#121821","border":"#223043","muted":"#8aa0b8","quake":"#ff7a45","fire":"#ff6a1a","storm":"#5ab4ff","pandemic":"#35d07f"}},"links":[],"phase":2},{"key":"buyrunuz","engine":"studio","kind":"game","frame":"phone","name":"Buyrunuz","stage":"live","platforms":["iOS","Android"],"sectors":["gaming"],"tagline":{"en":"A cozy kart game with a Turkish soul.","tr":"Türk ruhlu, sıcacık bir go-kart yarışı."},"description":{"en":"A cozy kart-style driving game through Turkish neighbourhoods — tea gardens, bazaars, seaside roads. Portfolio value: team morale, a brand-friendly casual title for cross-promo, and a test of ads/IAP in games.","tr":"Türk mahallelerinde — çay bahçeleri, çarşılar, sahil yolları — sıcacık bir go-kart yarışı oyunu. Portföy değeri: ekip morali, çapraz tanıtım için marka dostu bir oyun ve oyunlarda reklam/IAP testi."},"user":{"en":"Casual mobile players; families.","tr":"Gündelik mobil oyuncular; aileler."},"aiCore":{"en":"AI-generated track variations and character banter; AI-assisted asset pipeline.","tr":"Yapay zekâ ile üretilen pist varyasyonları ve karakter muhabbeti; yapay zekâ destekli görsel üretim hattı."},"money":{"en":"Rewarded ads + cosmetic IAP. Decision gate: soft launch by month 9 or park.","tr":"Ödüllü reklam + kozmetik IAP. Karar kapısı: 9. ayda yumuşak lansman ya da park."},"edge":{"en":"Kept cheap: 10% time, zero paid acquisition until it passes the same three gates.","tr":"Ucuz tutulur: %10 zaman, üç kapıyı geçene kadar sıfır ücretli edinim."},"brand":{"bg":"#FFE8C2","fg":"#3A2418","accent":"#E63946","fontDisplay":"Fredoka","fontBody":"Nunito","fontsCss2":["Fredoka:wght@600;700","Nunito:wght@600;800"],"extra":{"sea":"#3FB0D8","grass":"#7BC96F","road":"#5E5E66"}},"links":[],"phase":2},{"key":"osint","engine":"agents","kind":"agent","frame":"browser","name":{"en":"OSINT Agent","tr":"OSINT Ajanı"},"stage":"live","platforms":[{"en":"Web app","tr":"Web uygulaması"},{"en":"PDF report","tr":"PDF rapor"},{"en":"API","tr":"API"}],"sectors":["security","finance","legal"],"tagline":{"en":"Automated open-source due diligence, sourced line by line.","tr":"Otomatik açık kaynak durum tespiti, satır satır kaynaklı."},"description":{"en":"Automated open-source due diligence on companies and individuals: a cleanliness score out of 10 with a deterministic rationale and a ceiling when registries could not be checked, a sourced findings report as PDF and a workbook mapping every finding to its source. Single and bulk (Excel) research; sanctions, PEP, MASAK, SPK and wanted-list screening with dated snapshots; court-record role verification (plaintiff or defendant); 'not found' and 'could not be checked' said explicitly. In production at one bank's credit and compliance desk; references on request.","tr":"Şirket ve kişiler için otomatik açık kaynak durum tespiti: deterministik gerekçeli ve siciller kontrol edilemediğinde tavan uygulanan 10 üzerinden temizlik skoru, kaynaklı bulgu raporu (PDF) ve her bulguyu kaynağına bağlayan çalışma kitabı. Tekil ve toplu (Excel) araştırma; tarihli anlık görüntülerle yaptırım, PEP, MASAK, SPK ve arananlar taraması; mahkeme kayıtlarında rol teyidi (davacı mı davalı mı); 'bulunamadı' ve 'kontrol edilemedi' açıkça yazılır. Bir bankanın kredi ve uyum masasında üretimde; referans talep üzerine."},"user":{"en":"Credit and factoring companies, VC/PE funds, holdings' investment committees, law firms, HR for executive hires.","tr":"Kredi ve faktoring şirketleri, VC/PE fonları, holding yatırım komiteleri, hukuk büroları, üst düzey işe alımlar için İK."},"aiCore":{"en":"Multi-source collection, entity resolution, adverse-media search, published court decisions and public registries, UBO mapping, scoring; human review layer for regulated buyers; KVKK lawful basis and a controller–processor agreement per customer.","tr":"Çok kaynaklı toplama, varlık çözümleme, olumsuz basın taraması, yayımlanmış mahkeme kararları ve kamuya açık siciller, nihai yararlanıcı haritası, skorlama; düzenlemeye tabi alıcılar için insan inceleme katmanı; müşteri başına KVKK hukuki dayanağı ve veri işleme sözleşmesi."},"money":{"en":"$1,200/month per customer (seat bundle + report credits); per-report for occasional buyers; API for platforms such as Venturi. External sales from month 6.","tr":"Müşteri başına aylık $1.200 (koltuk paketi + rapor kredisi); ara sıra alanlar için rapor başına; Venturi gibi platformlar için API. Dış satış 6. aydan."},"edge":{"en":"Already used in real pre-screening at an affiliated bank; Turkish-language sources and registries that global KYC tools handle poorly; a report format buyers already accept.","tr":"Bağlı bir bankada gerçek ön taramada kullanılıyor; küresel KYC araçlarının zayıf kaldığı Türkçe kaynak ve siciller; alıcıların zaten kabul ettiği rapor biçimi."},"brand":{"bg":"#f5f7fb","fg":"#172443","accent":"#234dd7","fontDisplay":"Manrope","fontBody":"DM Sans","fontsCss2":["Manrope:wght@600;700;800","DM+Sans:wght@400;500;600"],"extra":{"hi":"#158365","md":"#a25d1b","lo":"#b8342a","new":"#4c3f95","cyan":"#35b4c7","paper":"#ffffff","line":"#e6eaf2"}},"links":[],"phase":3},{"key":"triage","engine":"agents","kind":"automation","frame":"browser","name":{"en":"Lead triage","tr":"Talep triyajı"},"stage":"build","platforms":[{"en":"Webhook service","tr":"Webhook servisi"},{"en":"Dashboard","tr":"Panel"},{"en":"CRM","tr":"CRM"}],"sectors":["marketing","security"],"tagline":{"en":"Every demo request scored, routed and written to the CRM in seconds.","tr":"Her demo talebi saniyeler içinde puanlanır, yönlendirilir ve CRM'e yazılır."},"description":{"en":"Orchestration builds in three steps — paid discovery, a bounded implementation (indicative from $40k) and managed operation (indicative $3k/month) — for reporting, reconciliation, research, customer ops and IC memos. This case: a cybersecurity vendor's demo requests are scored real/review/fake, classified against SLA, routed to the right rep, emailed and written to the CRM. Nothing deleted; every decision explained.","tr":"Üç adımlı orkestrasyon kurulumları — ücretli keşif, sınırlı kurulum (gösterge: 40 bin dolardan) ve yönetilen işletim (gösterge: aylık 3 bin dolar) — raporlama, mutabakat, araştırma, müşteri operasyonu ve yatırım komitesi notu için. Bu vaka: bir siber güvenlik firmasının demo talepleri gerçek/incele/sahte puanlanır, SLA'ya göre sınıflanır, doğru temsilciye atanır, e-posta ve CRM kaydı yazılır. Hiçbir şey silinmez; her karar açıklanır."},"user":{"en":"Holdings, mid-caps and their portfolio companies with an AI committee and no delivery team.","tr":"Yapay zekâ komitesi olan ama teslim ekibi olmayan holdingler, orta ölçekli şirketler ve portföy şirketleri."},"aiCore":{"en":"Claude-based scoring with deterministic rules first, explainable decisions, human review for borderline cases; n8n or code orchestration; audit log.","tr":"Önce deterministik kurallar sonra Claude puanlama, açıklanabilir kararlar, sınırdaki vakalar için insan incelemesi; n8n ya da kod orkestrasyonu; denetim kaydı."},"money":{"en":"Paid discovery, then a bounded build (indicative from $40k) and managed operation (indicative $3k/month); price follows integration scope, data costs and service obligations. Acceptance metrics and operating cost are agreed before the build.","tr":"Ücretli keşif, ardından sınırlı kurulum (gösterge: 40 bin dolardan) ve yönetilen işletim (gösterge: aylık 3 bin dolar); fiyat entegrasyon kapsamına, veri maliyetlerine ve hizmet yükümlülüklerine göre belirlenir. Kabul ölçütleri ve işletim maliyeti kurulumdan önce kararlaştırılır."},"edge":{"en":"Every module the studio builds (auth, paywall, streaming AI, pipelines) is also sellable to enterprises — delivery is reuse, not consulting hours.","tr":"Stüdyonun yaptığı her modül kurumlara da satılabilir — teslim danışmanlık saati değil yeniden kullanım."},"brand":{"bg":"#0F1720","fg":"#E6EEF5","accent":"#3FD68F","fontDisplay":"IBM Plex Sans","fontBody":"IBM Plex Sans","fontsCss2":["IBM+Plex+Sans:wght@400;500;600","IBM+Plex+Mono:wght@400;500"],"extra":{"panel":"#16212D","line":"#24323F","warn":"#F2B84B","bad":"#F0665A","info":"#6FA8FF"}},"links":[]},{"key":"content","engine":"agents","kind":"automation","frame":"browser","name":{"en":"Social Media Content Agent","tr":"Sosyal Medya İçerik Ajanı"},"stage":"live","platforms":[{"en":"Web app","tr":"Web uygulaması"},"Instagram · LinkedIn · X · TikTok"],"sectors":["marketing","media"],"tagline":{"en":"From a one-line brief to an approval queue to four platforms.","tr":"Tek satırlık brieften onay kuyruğuna, oradan dört platforma."},"description":{"en":"A production Next.js + Supabase app that takes briefs, generates on-brand posts with Claude (writer agent trained on brand-voice examples), manages an approval queue and publishes to Instagram, LinkedIn, X and TikTok through a unified publishing API, with analytics and agent logs. Built for a holding's communications team.","tr":"Brief alan, marka sesi örnekleriyle Claude'a gönderi yazdıran, onay kuyruğu yöneten ve Instagram, LinkedIn, X ve TikTok'a tek API ile yayınlayan üretimde bir Next.js + Supabase uygulaması; analitik ve ajan kayıtlarıyla. Bir holdingin iletişim ekibi için yapıldı."},"user":{"en":"Communications and marketing teams inside holdings and portfolio companies.","tr":"Holdinglerin ve portföy şirketlerinin iletişim ve pazarlama ekipleri."},"aiCore":{"en":"Writer agent with brand-voice few-shots, platform-specific variants, hashtags and posting-time suggestions; humans approve before anything publishes.","tr":"Marka sesi örnekleriyle yazar ajan, platforma özel varyantlar, hashtag ve zaman önerisi; yayından önce insan onayı."},"money":{"en":"Sold as an orchestration build + run fee; also the internal creative engine for Kulis, The Istanbul Times and Kapi.","tr":"Orkestrasyon kurulumu + işletme ücreti olarak satılır; Kulis, The Istanbul Times ve Kapi için dahili yaratıcı motor."},"edge":{"en":"Approval-first by design: the agent never publishes autonomously.","tr":"Tasarım gereği önce onay: ajan asla kendi başına yayınlamaz."},"brand":{"bg":"#FAFAF7","fg":"#1E1E1E","accent":"#0E4A3A","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,500..800","Instrument+Sans:wght@400;500;600"],"extra":{"ig":"#E1306C","li":"#0A66C2","x":"#111111","tt":"#00F2EA","ok":"#1FBF75"}},"links":[],"phase":1},{"key":"neonpong","engine":"studio","kind":"game","frame":"browser","name":"Neon Pong","stage":"live","platforms":["Web"],"sectors":["gaming"],"tagline":{"en":"Four levels of opponent. One very fast ball.","tr":"Dört zorluk seviyesi. Çok hızlı bir top."},"description":{"en":"A neon arcade pong for the browser: play the computer on four difficulties or a friend on one keyboard, first to 5, 7, 11 or 21, with rally and best-rally counters, a serve countdown, sound and music. Built end-to-end with AI coding agents as a shipping test for the games line.","tr":"Tarayıcıda neon bir arcade pong: bilgisayara karşı dört zorlukta ya da tek klavyede bir arkadaşınla, 5, 7, 11 ya da 21'e kadar; ralli ve en iyi ralli sayaçları, servis geri sayımı, ses ve müzik. Oyun hattı için bir yayına alma denemesi olarak yapay zekâ kodlama ajanlarıyla baştan sona üretildi."},"user":{"en":"Casual browser players; a cross-promo and recruiting toy.","tr":"Gündelik tarayıcı oyuncuları; çapraz tanıtım ve işe alım oyuncağı."},"aiCore":{"en":"Built with AI coding agents; the four CPU levels (Easy · Medium · Hard · Insane) are hand-tuned reflex and prediction models.","tr":"Yapay zekâ kodlama ajanlarıyla yapıldı; dört bilgisayar seviyesi (Easy · Medium · Hard · Insane) elle ayarlanmış refleks ve tahmin modelleri."},"money":{"en":"None — an experiment; a rewarded-ad test candidate later.","tr":"Yok — deney; ileride ödüllü reklam testi adayı."},"edge":{"en":"Proof that a small game ships in days on the shared stack; a test bed for ads and web billing in games.","tr":"Ortak altyapıda küçük bir oyunun günler içinde çıktığının kanıtı; oyunlarda reklam ve web ödemesi için test alanı."},"brand":{"bg":"#070A1A","fg":"#E8ECFF","accent":"#22E5FF","fontDisplay":"Orbitron","fontBody":"IBM Plex Mono","fontsCss2":["Orbitron:wght@700;900","IBM+Plex+Mono:wght@400;500"],"extra":{"pink":"#FF3D7F","gold":"#F5C542","grid":"#121a3a"}},"links":[],"phase":2},{"key":"hexa","engine":"studio","kind":"game","frame":"phone","name":{"en":"Hexan","tr":"Hexan"},"stage":"live","platforms":["iOS","Android"],"sectors":["gaming"],"tagline":{"en":"A Catan-style board game, online with friends.","tr":"Arkadaşlarla çevrimiçi, Catan tarzı bir masa oyunu."},"description":{"en":"A settlement-and-trade board game for four to six players on a hex map: sign in, open or join a lobby with a six-character code, roll, gather wood, brick, wheat, sheep and ore, build roads, settlements and cities, trade and race to victory points. Expo client, Supabase auth, a socket.io game server.","tr":"Altıgen haritada dört-altı kişilik yerleşim ve ticaret masa oyunu: giriş yap, altı haneli kodla lobi aç ya da katıl, zar at, odun, tuğla, buğday, koyun ve maden topla, yol, yerleşim ve şehir kur, takas yap, zafer puanına koş. Expo istemci, Supabase kimlik, socket.io oyun sunucusu."},"user":{"en":"Board-game groups who want to play remotely; families.","tr":"Uzaktan oynamak isteyen masa oyunu grupları; aileler."},"aiCore":{"en":"AI opponents and a rules coach later; built with AI coding agents.","tr":"İleride yapay zekâ rakipler ve kural koçu; yapay zekâ kodlama ajanlarıyla yapıldı."},"money":{"en":"Cosmetic packs and private-lobby subscriptions once it passes the gates.","tr":"Kapıları geçince kozmetik paketler ve özel lobi aboneliği."},"edge":{"en":"Real-time multiplayer on the shared stack, reusable for every future social game. Hexan is the product's own brand; 'Catan-style' only describes the genre, and that name is its owner's trademark.","tr":"Ortak altyapıda gerçek zamanlı çok oyunculu; gelecekteki her sosyal oyun için yeniden kullanılır. Hexan ürünün kendi markasıdır; 'Catan tarzı' yalnızca türü anlatır, bu ad sahibinin tescilli markasıdır."},"brand":{"bg":"#1a0a00","fg":"#F8EEDC","accent":"#f5c842","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#2a1000","elevated":"#3b1a00","border":"#5a3000","players":["#e74c3c","#3498db","#2ecc71","#f39c12","#9b59b6","#1abc9c"],"wood":"#2E7D32","brick":"#B5532A","wheat":"#E0B13C","sheep":"#8BC34A","ore":"#6D6D7A"}},"links":[],"phase":1,"slug":"hexan"},{"key":"sector","engine":"agents","kind":"agent","frame":"browser","name":{"en":"Sector Research Agent","tr":"Sektör Araştırma Ajanı"},"stage":"live","platforms":[{"en":"Web report","tr":"Web raporu"},{"en":"PDF","tr":"PDF"},{"en":"JSON scorecard","tr":"JSON skor kartı"}],"sectors":["finance"],"tagline":{"en":"Bottom-up sector intelligence that corrects the top-down hype.","tr":"Yukarıdan şişirilmiş rakamları düzelten, aşağıdan yukarı sektör istihbaratı."},"description":{"en":"A multi-agent research run that turns a sector question into a sourced report: bottom-up TAM/SAM/SOM cross-checked against top-down reports (with 'inflated' badges), growth drivers split into proven and narrative, the regulation timeline, Porter forces, Türkiye and MENA chapters, investment climate, base/good/bad scenarios, a sector-attractiveness score out of 10 with evidence layers K1–K4 and an explicit ceiling when data is thin.","tr":"Bir sektör sorusunu kaynaklı rapora çeviren çok ajanlı araştırma: yukarıdan aşağı raporlarla çapraz kontrol edilmiş (şişkin rozetli) aşağıdan yukarı TAM/SAM/SOM, kanıtlı ve anlatı ayrımlı büyüme sürükleyicileri, regülasyon takvimi, Porter kuvvetleri, Türkiye ve MENA bölümleri, yatırım iklimi, baz/iyi/kötü senaryolar, K1–K4 kanıt katmanlı ve veri zayıfsa tavan uygulanan 10 üzerinden sektör cazibesi skoru."},"user":{"en":"Investment committees of holdings and funds; corporate strategy teams.","tr":"Holding ve fonların yatırım komiteleri; kurumsal strateji ekipleri."},"aiCore":{"en":"Orchestrated sub-agents (market, competition, regulation, sentiment) with web research, official-source verification, echo de-duplication of news, a deterministic scoring rubric and a JSON scorecard for downstream models.","tr":"Web araştırması, resmî kaynak doğrulaması, haber eko ayıklaması, deterministik puanlama rubriği ve sonraki modeller için JSON skor kartıyla orkestre edilmiş alt ajanlar (pazar, rekabet, mevzuat, sentiment)."},"money":{"en":"Sold with the investment-committee suite; per report or as a retainer add-on — talk to us.","tr":"Yatırım komitesi paketiyle; rapor başına ya da danışmanlık sözleşmesine ek — bize yazın."},"edge":{"en":"Every number carries its evidence layer; seller claims are labelled and tested. In production for an affiliated holding's investment team.","tr":"Her rakam kanıt katmanını taşır; satıcı iddiaları etiketlenir ve sınanır. Bağlı bir holdingin yatırım ekibinde üretimde."},"brand":{"bg":"#f5f7f9","fg":"#0f1720","accent":"#0c6b9e","fontDisplay":"Libre Baskerville","fontBody":"Instrument Sans","fontsCss2":["Libre+Baskerville:wght@400;700","Instrument+Sans:wght@400;500;600"],"extra":{"good":"#116655","warn":"#8a5300","bad":"#98252a","panel":"#ffffff","line":"#dce2ea","mast":"#0d3a5c"}},"links":[],"phase":3},{"key":"regulation","engine":"agents","kind":"agent","frame":"browser","name":{"en":"Regulation Radar Agent","tr":"Regülasyon Radarı Ajanı"},"stage":"live","platforms":[{"en":"Web report","tr":"Web raporu"},{"en":"Monitoring alerts","tr":"İzleme uyarıları"}],"sectors":["legal","finance"],"tagline":{"en":"What the law says today, what is about to change, and which clause to read first.","tr":"Kanun bugün ne diyor, yakında ne değişecek, hangi madde önce okunmalı."},"description":{"en":"Maps the rules that touch a sector or a deal — laws, secondary regulation, circulars, EU directives — verifies them against official gazettes and court databases, estimates compliance cost, then scores upcoming changes with an RDO (likelihood-of-change) score, a time window and a direction, names the clause that decides the thesis, and leaves a monitoring plan behind.","tr":"Bir sektöre ya da işleme dokunan kuralları — kanun, ikincil mevzuat, genelge, AB direktifi — haritalar, Resmî Gazete ve yargı veri tabanlarıyla doğrular, uyum maliyetini tahmin eder; sonra yaklaşan değişiklikleri RDO (değişme olasılığı) puanı, zaman penceresi ve yönle puanlar, tezi belirleyen maddeyi adlandırır ve bir izleme planı bırakır."},"user":{"en":"Deal teams, compliance and strategy in holdings, funds and regulated companies.","tr":"Holding, fon ve düzenlemeye tabi şirketlerde işlem, uyum ve strateji ekipleri."},"aiCore":{"en":"Retrieval over official sources, court-database checks (constitutional-court and competition-authority decisions), plain-language rewriting, RDO scoring, scheduled re-runs for monitoring.","tr":"Resmî kaynaklarda arama, yargı veri tabanı kontrolleri (AYM, Rekabet Kurumu), sade dille yeniden yazım, RDO puanlama, izleme için zamanlanmış yeniden çalıştırma."},"money":{"en":"Part of the investment-committee suite; monitoring as a monthly add-on — talk to us.","tr":"Yatırım komitesi paketinin parçası; izleme aylık ek hizmet — bize yazın."},"edge":{"en":"Plain Turkish, official sources only, and an explicit 'lawyer confirmation required' line — a radar, not legal advice. In production for an affiliated holding.","tr":"Sade Türkçe, yalnız resmî kaynak ve açık bir 'avukat teyidi gerekir' satırı — hukuki görüş değil, radar. Bağlı bir holdingde üretimde."},"brand":{"bg":"#f6f8f7","fg":"#17211c","accent":"#0f7a5a","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600"],"extra":{"good":"#1a7f4b","bad":"#b3261e","warn":"#8a6d00","mast":"#08432f"}},"links":[],"phase":3},{"key":"valuation","engine":"agents","kind":"agent","frame":"browser","name":{"en":"Company Valuation Agent","tr":"Şirket Değerleme Ajanı"},"stage":"live","platforms":[{"en":"Web report","tr":"Web raporu"},{"en":"Excel bridge","tr":"Excel köprüsü"}],"sectors":["finance"],"tagline":{"en":"A valuation bridge from official comps to the price on the table.","tr":"Resmî emsallerden masadaki fiyata değerleme köprüsü."},"description":{"en":"Builds the comparables from sources that hold up in a committee — competition-authority merger decisions, listed peers — turns them into a floor-to-ceiling band on the target's revenue and cash EBITDA, restates accounting traps (capitalised R&D, tax-shield sunsets), discounts uncontrollable growth, and states in plain language whether the ask is defensible and which synergy belongs to the buyer.","tr":"Komitede ayakta kalan kaynaklardan — Rekabet Kurulu birleşme kararları, halka açık emsaller — karşılaştırılabilirleri kurar, hedefin cirosu ve nakit FAVÖK'ü üzerinde taban-tavan bandına çevirir, muhasebe tuzaklarını (aktifleştirilmiş Ar-Ge, biten vergi kalkanı) düzeltir, kontrol dışı büyümeyi iskontolar ve istenen fiyatın savunulabilir olup olmadığını, hangi sinerjinin alıcıya ait olduğunu sade dille söyler."},"user":{"en":"Investment committees, corporate-venture and M&A teams.","tr":"Yatırım komiteleri, kurumsal girişim ve birleşme-satın alma ekipleri."},"aiCore":{"en":"Comps retrieval and verification, multiple arithmetic with source anchors, accounting normalisation rules, scenario tables and a bridge chart; hands numbers to the one-pager agent.","tr":"Emsal bulma ve doğrulama, kaynak çıpalı çarpan aritmetiği, muhasebe normalizasyon kuralları, senaryo tabloları ve köprü grafiği; rakamları one-pager ajanına aktarır."},"money":{"en":"Part of the investment-committee suite; per deal — talk to us.","tr":"Yatırım komitesi paketinin parçası; işlem başına — bize yazın."},"edge":{"en":"Multiples applied to cash, not paper profit; every anchor is an official decision or a listed price. In production for an affiliated holding.","tr":"Çarpan kâğıt kârına değil nakde uygulanır; her çıpa resmî bir karar ya da borsa fiyatı. Bağlı bir holdingde üretimde."},"brand":{"bg":"#F7F8FA","fg":"#142735","accent":"#146A5B","fontDisplay":"Bricolage Grotesque","fontBody":"IBM Plex Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","IBM+Plex+Sans:wght@400;500;600"],"extra":{"navy":"#142735","warn":"#8a5300","bad":"#98252a","line":"#D9DFDC"}},"links":[],"phase":2},{"key":"onepager","engine":"agents","kind":"agent","frame":"browser","name":{"en":"One-Pager Agent","tr":"One-Pager Ajanı"},"stage":"live","platforms":[{"en":"A4 HTML/PDF","tr":"A4 HTML/PDF"}],"sectors":["finance"],"tagline":{"en":"From a data room to a one-page investment memo.","tr":"Veri odasından tek sayfalık yatırım notuna."},"description":{"en":"Reads the deck, financial statements and spreadsheets a company sends, checks the claims against public sources, and lays out a one-page memo in the holding's own format: company, products, ownership, competition, strengths, risks with a warning box when a claim does not hold, an assessment, plus the financial summary, key metrics, comparable multiples, milestones and the group-integration angle.","tr":"Şirketin gönderdiği sunumu, mali tabloları ve hesap tablolarını okur, iddiaları kamuya açık kaynaklarla sınar ve holdingin kendi formatında tek sayfalık not çıkarır: şirket, ürünler, ortaklık, rekabet, artılar, tutmayan iddia için uyarı kutulu riskler, değerlendirme; artı özet finansallar, kilit metrikler, emsal çarpanlar, kilometre taşları ve grup entegrasyonu açısı."},"user":{"en":"Holding and fund investment teams that screen dozens of companies a month.","tr":"Ayda onlarca şirket eleyen holding ve fon yatırım ekipleri."},"aiCore":{"en":"PDF and spreadsheet extraction, claim-checking with web search, financial ratio computation, a fixed A4 template with print-safe CSS; three inputs from the analyst (reference manager, acquiring entity, integration note).","tr":"PDF ve tablo çıkarımı, web aramasıyla iddia kontrolü, finansal oran hesabı, baskıya uygun sabit A4 şablon; analistten üç girdi (referans yönetici, devralacak şirket, entegrasyon notu)."},"money":{"en":"Part of the investment-committee suite; per memo or monthly volume — talk to us.","tr":"Yatırım komitesi paketinin parçası; not başına ya da aylık hacim — bize yazın."},"edge":{"en":"The format the committee already reads, filled in minutes and honest about what the documents do not show. In production for an affiliated holding.","tr":"Komitenin zaten okuduğu format, dakikalar içinde ve belgelerin göstermediği şeyi açıkça söyleyerek. Bağlı bir holdingde üretimde."},"brand":{"bg":"#FFFFFF","fg":"#222222","accent":"#1F3864","fontDisplay":"Instrument Sans","fontBody":"Instrument Sans","fontsCss2":["Instrument+Sans:wght@400;500;600;700"],"extra":{"navy":"#1F3864","blue":"#2E75B6","rowlabel":"#e8eef5","warnbg":"#fff3cd","warnline":"#e0a800"}},"links":[],"phase":3},{"key":"endeks","engine":"studio","kind":"app","frame":"phone","name":{"en":"Endex","tr":"Endex"},"stage":"idea","platforms":["iOS","Android","Web"],"sectors":["finance"],"tagline":{"en":"Markets, crypto and balance sheets on one screen.","tr":"Borsa, kripto ve bilançolar tek ekranda."},"description":{"en":"A portfolio and research app for Turkish retail investors: BIST, US stocks, crypto and funds in one portfolio; AI-read financial statements with Fintables-style ratios; KAP disclosures summarised in plain Turkish; 'why did it move' explanations with sources; watchlists and alerts. Analytics and education only — no order execution and no personalised advice; brokers connect later through licensed partners.","tr":"Türk bireysel yatırımcı için portföy ve araştırma uygulaması: BIST, ABD hisseleri, kripto ve fonlar tek portföyde; yapay zekânın okuduğu bilançolar ve Fintables tarzı rasyolar; KAP açıklamalarının sade Türkçe özeti; kaynaklı 'neden hareket etti' açıklamaları; izleme listeleri ve uyarılar. Yalnızca analiz ve eğitim — emir iletimi ve kişiye özel tavsiye yok; aracı kurumlar ileride lisanslı ortaklarla bağlanır."},"user":{"en":"Retail investors who hold both stocks and crypto and read too many screens.","tr":"Hem hisse hem kripto tutan, çok fazla ekran okuyan bireysel yatırımcılar."},"aiCore":{"en":"Statement reading and ratio extraction, disclosure summaries, sourced movement explanations; deterministic ratio maths, model only for language.","tr":"Bilanço okuma ve rasyo çıkarma, açıklama özetleri, kaynaklı hareket açıklamaları; rasyolar deterministik, model yalnızca dil için."},"money":{"en":"Monthly subscription tiers; later data and API licensing.","tr":"Aylık abonelik kademeleri; ileride veri ve API lisansı."},"edge":{"en":"One screen where Turkish investors today juggle a broker app, a crypto exchange and a ratio site; every number carries its source.","tr":"Türk yatırımcının bugün aracı kurum uygulaması, kripto borsası ve rasyo sitesi arasında dolaştığı işi tek ekranda yapar; her rakamın kaynağı var."},"brand":{"bg":"#0B1220","fg":"#E6EDF7","accent":"#3DDC97","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600","IBM+Plex+Mono:wght@400;500"],"extra":{"surface":"#111B2E","elevated":"#182640","border":"#243654","down":"#FF6B6B","mono":"IBM Plex Mono","gold":"#E3C06A"}},"links":[],"slug":"endex"},{"key":"saha","engine":"studio","kind":"app","frame":"phone","name":{"en":"Sportista","tr":"Sportista"},"stage":"idea","platforms":["iOS","Android","Web"],"sectors":["sports"],"tagline":{"en":"Pre-match intelligence and live analytics, beyond the score.","tr":"Maç öncesi istihbarat ve canlı analiz, skorun ötesinde."},"description":{"en":"A sports analytics app for football, basketball, tennis and American football: pre-match briefings with form, injuries, expected goals and calibrated win probabilities; a live match centre with momentum, xG race and live probabilities; player and lineup analytics. A B2B layer licenses the models to licensed operators and media. In Türkiye sports betting runs only through licensed operators, so the betting use is B2B model licensing to them — Sportista has no consumer betting product.","tr":"Futbol, basketbol, tenis ve Amerikan futbolu için spor analiz uygulaması: form, sakatlık, beklenen gol ve kalibre edilmiş kazanma olasılıklarıyla maç öncesi brifing; momentum, xG yarışı ve canlı olasılıkla canlı maç merkezi; oyuncu ve kadro analizi. B2B katmanı modelleri lisanslı operatörlere ve medyaya lisanslar. Türkiye'de spor bahsi yalnızca lisanslı operatörler üzerinden yapılabildiği için bahis kullanımı onlara B2B model lisansıdır — Sportista'nın tüketiciye yönelik bahis ürünü yok."},"user":{"en":"Fans and fantasy players who want more than Flashscore-style scores; media desks and licensed operators for the model layer.","tr":"Flashscore tarzı skordan fazlasını isteyen taraftarlar ve fantezi lig oyuncuları; model katmanı için medya masaları ve lisanslı operatörler."},"aiCore":{"en":"Probability models per sport with calibration reports; event-stream summarisation for live commentary; player-similarity embeddings.","tr":"Spor başına kalibrasyon raporlu olasılık modelleri; canlı anlatım için olay akışı özetleme; oyuncu benzerlik vektörleri."},"money":{"en":"Freemium subscription for fans; model licensing and data feeds for licensed operators (B2B only) and media.","tr":"Taraftara freemium abonelik; lisanslı operatörlere (yalnızca B2B) ve medyaya model lisansı ve veri akışı."},"edge":{"en":"Model-first where incumbents are score-first; the same models sell twice — to fans and to licensed businesses.","tr":"Rakipler skor odaklıyken model odaklı; aynı modeller iki kez satılır — taraftara ve lisanslı işletmelere."},"brand":{"bg":"#0A1F14","fg":"#F1F7F3","accent":"#B4FF3A","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600","IBM+Plex+Mono:wght@400;500"],"extra":{"surface":"#10291B","elevated":"#173524","border":"#24483A","hot":"#FF7A59","mono":"IBM Plex Mono"}},"links":[],"slug":"sportista"},{"key":"deger","engine":"studio","kind":"app","frame":"phone","name":{"en":"Değer (working name)","tr":"Değer (çalışma adı)"},"stage":"idea","platforms":["iOS","Android","Web"],"tagline":{"en":"A digital broker for homes, cars, boats and watches — priced, listed and sold safely.","tr":"Ev, araç, tekne ve saat için dijital emlakçı — fiyatlanır, ilana çıkar, güvenle satılır."},"description":{"en":"An AI agent that does a broker's job for the valuable things you own. It prices the asset from comparable sales and condition photos, writes and verifies the listing (ownership or the owner's authorisation is checked before it goes live), finds buyers and verifies who they are, arranges viewings, test drives, sea trials and watch authentication with partners, and walks both sides to a safe close: for homes and used cars, the payment system set up under Turkish regulation in which title and money change hands at the same moment; for boats and watches, a licensed payment partner that holds the money until handover. Need cash instead of a sale? 'Değer Rehin' shows offers from a licensed lending partner against a car, boat or watch. Real-estate and vehicle deals run through Değer or partners holding the Ministry of Trade authorisation certificate; Değer never lends — the licensed partner writes the loan.","tr":"Sahip olduğunuz değerli varlıklar için emlakçının işini yapan bir yapay zekâ ajanı. Varlığı emsal satışlardan ve durum fotoğraflarından fiyatlar, ilanı yazar ve doğrular (ilan yayına girmeden mülkiyet ya da sahibin verdiği yetki kontrol edilir), alıcıyı bulur ve kimliğini doğrular, gezme, test sürüşü, deniz denemesi ve saat orijinallik kontrolünü ortaklarla ayarlar ve iki tarafı güvenli devre kadar götürür: konut ve ikinci el araçta mevzuatla kurulan, mülkiyetle bedelin aynı anda el değiştirdiği ödeme sistemi; tekne ve saatte bedeli teslime kadar tutan lisanslı ödeme ortağı. Satmak yerine nakit mi lazım? 'Değer Rehin', araç, tekne ya da saat karşılığında lisanslı bir kredi ortağının tekliflerini gösterir. Konut ve araç işlemleri Değer ya da Ticaret Bakanlığı yetki belgesine sahip ortaklar üzerinden yürür; Değer asla kredi vermez — krediyi lisanslı ortak yazar."},"user":{"en":"Owners of homes, cars, boats and watches who want a fair price and a safe sale without doing the broker's work themselves; buyers who want verified listings and a clean close.","tr":"Emlakçının işini kendisi yapmadan adil fiyat ve güvenli satış isteyen konut, araç, tekne ve saat sahipleri; doğrulanmış ilan ve temiz bir devir isteyen alıcılar."},"aiCore":{"en":"Valuation from comparable sales and condition photos with a confidence band; listing text and photo checklists; ownership and authorisation checks through the Ministry of Trade's verification systems before a home or car listing goes live; buyer-identity checks and fraud, duplicate and fake-listing detection; a scheduling agent for viewings; document and step tracking to the close. The valuation is an estimate, not a purchase offer.","tr":"Emsal satış ve durum fotoğraflarından güven aralıklı değerleme; ilan metni ve fotoğraf kontrol listesi; konut ya da araç ilanı yayına girmeden Ticaret Bakanlığı doğrulama sistemleri üzerinden mülkiyet ve yetki kontrolü; alıcı kimlik kontrolü ve sahtecilik, mükerrer ve sahte ilan tespiti; gezmeler için takvim ajanı; devre kadar belge ve adım takibi. Değerleme bir tahmindir, satın alma teklifi değildir."},"money":{"en":"A success fee on completed sales, within the legal fee caps where they apply; paid valuation reports and listing packs; partner fees from inspection, insured storage and licensed lenders, always shown to the user.","tr":"Tamamlanan satışlarda, uygulanan yerlerde yasal üst sınırlar içinde başarı ücreti; ücretli değerleme raporları ve ilan paketleri; ekspertiz, sigortalı saklama ve lisanslı kredi ortaklarından, kullanıcıya her zaman gösterilen ortak ücretleri."},"edge":{"en":"Where a portal publishes an ad, Değer runs the sale: one agent from price to handover across four asset classes, built on the verified-listing and same-moment title-and-payment rules Turkish regulation sets for homes and used cars. Cash against the asset comes through a licensed partner, not a grey market. Later, Decorum's virtual staging can dress home listings, always labelled.","tr":"Bir portal ilanı yayınlarken Değer satışı yürütür: dört varlık sınıfında fiyattan teslime tek ajan; Türk mevzuatının konut ve ikinci el araç için koyduğu doğrulanmış ilan ve mülkiyetle bedelin aynı anda el değiştirmesi kuralları üzerine kurulu. Varlık karşılığı nakit gri piyasadan değil, lisanslı ortaktan gelir. İleride Decorum'un sanal döşemesi konut ilanlarını, her zaman etiketli olarak giydirebilir."},"brand":{"bg":"#F6F1E7","fg":"#1C1A17","accent":"#B8792B","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#FFFDF8","elevated":"#EFE7D8","border":"#DDD2BF","ink2":"#5B554B","green":"#2E7D5B"}},"links":[],"slug":"deger","sectors":["marketplace","finance"]},{"key":"masa","engine":"studio","kind":"game","frame":"phone","name":"Kozy","stage":"live","platforms":["iOS"],"sectors":["gaming"],"tagline":{"en":"A table for one more game.","tr":"Bir el daha?"},"description":{"en":"A native SwiftUI game lounge. Okey against three local opponents, Pişti against one and the pass-the-phone Söz Sende deck are playable. Kahve has account, friends, invitations and room flows; a demo backend shows sample people and counts until live Supabase is configured. 101, Batak, chess, dama and other tables remain upcoming.","tr":"SwiftUI ile geliştirilmiş yerel oyun salonu. Üç bilgisayar rakibine karşı Okey, bir rakibe karşı Pişti ve telefonu elden ele dolaştıran Söz Sende oynanıyor. Kahve’de hesap, arkadaş, davet ve oda akışları var; canlı Supabase kurulana kadar örnek kişiler ve sayılar gösteriliyor. 101, Batak, satranç, dama ve diğer masalar henüz sırada."},"user":{"en":"Families and friend groups in Türkiye who already play these games at the table.","tr":"Bu oyunları zaten masada oynayan Türkiye'deki aileler ve arkadaş grupları."},"aiCore":{"en":"Local Okey and Pişti opponents are implemented. A rules coach and online fair-play systems are future work.","tr":"Okey ve Pişti için yerel bilgisayar rakipleri çalışıyor. Kural koçu ve çevrimiçi adil oyun sistemleri sonraki aşamada."},"money":{"en":"No ads, purchases or real-money play in the current build. Monetisation is undecided.","tr":"Mevcut yapıda reklam, satın alma veya gerçek parayla oyun yok. Gelir modeli henüz kararlaştırılmadı."},"edge":{"en":"A shared Turkish table-game home with playable native classics and a social foundation. Online game state is still being built.","tr":"Oynanabilir yerel klasiklerle Türkçe ortak oyun masası ve sosyal temel. Çevrimiçi oyun durumu henüz geliştiriliyor."},"brand":{"bg":"#F9F5EA","fg":"#203A2C","accent":"#104D38","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600"],"extra":{"felt":"#196E50","cream":"#F9F5EA","gold":"#F4C24F","ink":"#203A2C","red":"#C8322B"}},"links":[],"slug":"kozy","phase":2},{"key":"saglik","engine":"studio","kind":"app","frame":"browser","name":{"en":"sağlık.tamam","tr":"sağlık.tamam"},"stage":"idea","platforms":["Web"],"sectors":["health"],"tagline":{"en":"Drafts the note, cites the source, waits for the clinician.","tr":"Notun taslağını yazar, kaynağını gösterir, hekimi bekler."},"description":{"en":"A clinician-facing document and knowledge assistant: structured summaries of referral letters and lab reports with source pins, guideline questions answered with quoted passages, and draft notes that always wait for clinician approval. Built on synthetic or properly authorised data with an audit log. December 2026 MVP target with one clinical advisor and one design partner. No diagnosis, no clinical release without the required assessment.","tr":"Hekime dönük belge ve bilgi asistanı: sevk yazıları ve laboratuvar raporlarının kaynak işaretli yapılandırılmış özetleri, alıntıyla yanıtlanan kılavuz soruları ve her zaman hekim onayı bekleyen taslak notlar. Sentetik ya da usulünce yetkilendirilmiş veriyle, denetim kaydıyla. Aralık 2026 MVP hedefi; bir klinik danışman ve bir tasarım ortağı. Tanı yok; gerekli değerlendirme olmadan klinik yayın yok."},"user":{"en":"Clinics and health operators; individual clinicians for documentation.","tr":"Klinikler ve sağlık işletmeleri; dokümantasyon için hekimler."},"aiCore":{"en":"Document structuring and retrieval over authorised sources; every draft source-linked; clinician approval gate.","tr":"Yetkili kaynaklar üzerinde belge yapılandırma ve arama; her taslak kaynağa bağlı; hekim onay kapısı."},"money":{"en":"Subscription per organisation or professional plus scoped integration fees.","tr":"Kurum ya da uzman başına abonelik, kapsamı belirli entegrasyon ücreti."},"edge":{"en":"Turkish clinical documents and guidelines, expert-reviewed from day one; Pati becomes a later extension.","tr":"Türkçe klinik belge ve kılavuzlar, ilk günden uzman incelemeli; Pati ileride uzantı olur."},"brand":{"bg":"#F7FAFB","fg":"#10222B","accent":"#0E9F8E","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#FFFFFF","elevated":"#EAF3F2","border":"#D5E3E1","ink2":"#4A5C63","warn":"#B45309"}},"links":[],"slug":"saglik"},{"key":"hukuk","engine":"studio","kind":"app","frame":"browser","name":{"en":"hukuk.tamam","tr":"hukuk.tamam"},"stage":"idea","platforms":["Web"],"sectors":["legal"],"tagline":{"en":"Research with dated sources; contracts compared clause by clause.","tr":"Tarihli kaynakla araştırma; sözleşmelerin madde madde karşılaştırması."},"description":{"en":"A Turkish legal research and contract-review workspace: questions answered with dated sources and quoted evidence, a citation checker that flags obsolete or unverifiable references, and clause-by-clause comparison of two contract versions with risk flags. A qualified lawyer reviews outputs; Tamam sells software, not reserved legal services. December 2026 MVP target with two lawyer design partners.","tr":"Türk hukuku araştırma ve sözleşme inceleme çalışma alanı: tarihli kaynak ve alıntılanmış kanıtla yanıtlanan sorular, güncelliğini yitirmiş ya da doğrulanamayan atıfları işaretleyen atıf denetleyicisi, iki sözleşme sürümünün risk işaretli madde madde karşılaştırması. Çıktıları nitelikli bir avukat inceler; Tamam yazılım satar, avukatlık hizmeti değil. Aralık 2026 MVP hedefi; iki avukat tasarım ortağı."},"user":{"en":"Law firms and in-house legal teams.","tr":"Hukuk büroları ve şirket içi hukuk ekipleri."},"aiCore":{"en":"Retrieval over dated Turkish sources with quote-level citations; diff and risk classification for contracts; a lawyer-in-the-loop gate.","tr":"Tarihli Türkçe kaynaklar üzerinde alıntı düzeyinde atıflı arama; sözleşmelerde fark ve risk sınıflandırma; avukat onay kapısı."},"money":{"en":"Seat subscription with organisation plans and document-volume allowances.","tr":"Kurum planları ve belge hacmi kotalarıyla koltuk aboneliği."},"edge":{"en":"Turkish sources with dates and quotes where global tools guess; every citation testable.","tr":"Küresel araçların tahmin ettiği yerde tarihli ve alıntılı Türkçe kaynak; her atıf test edilebilir."},"brand":{"bg":"#F8F6F1","fg":"#1B1A1F","accent":"#7A1F2B","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#FFFFFF","elevated":"#EFEAE0","border":"#DAD3C5","ink2":"#5A5560","ok":"#2E7D5B","warn":"#B45309"}},"links":[],"slug":"hukuk"},{"key":"finans","engine":"studio","kind":"app","frame":"browser","name":{"en":"finans.tamam","tr":"finans.tamam"},"stage":"idea","platforms":["Web"],"sectors":["finance"],"tagline":{"en":"Research that cites, reconciliation that shows its work.","tr":"Kaynak gösteren araştırma, hesabını gösteren mutabakat."},"description":{"en":"A sourced research and financial-document reconciliation workspace for finance and corporate teams, grown from the five investment-committee agents: questions answered with citations, trial balances reconciled against bank statements and contracts with every mismatch explained, analyst approval on each item and a full audit trail. Paid B2B pilots first; no custody, payment service or personalised investment advice. December 2026 MVP target.","tr":"Finans ve kurumsal ekipler için kaynaklı araştırma ve finansal belge mutabakat çalışma alanı; beş yatırım komitesi ajanından büyüyor: atıflı yanıtlar, banka ekstresi ve sözleşmelerle mutabakatı yapılan mizanlar, açıklanan her fark, kalem başına analist onayı ve tam denetim izi. Önce ücretli B2B pilotlar; saklama, ödeme hizmeti ya da kişiye özel yatırım tavsiyesi yok. Aralık 2026 MVP hedefi."},"user":{"en":"Independent finance and corporate teams with a workflow owner and sample documents.","tr":"İş akışı sahibi ve örnek belgeleri olan bağımsız finans ve kurumsal ekipler."},"aiCore":{"en":"The OSINT, sector, regulation, valuation and one-pager agents as workflows; reconciliation with deterministic matching and model-written explanations; analyst gate.","tr":"OSINT, sektör, regülasyon, değerleme ve one-pager ajanları iş akışı olarak; deterministik eşleştirme ve model yazımı açıklamalarla mutabakat; analist kapısı."},"money":{"en":"Organisation subscriptions after paid pilots; per-seat plans.","tr":"Ücretli pilotların ardından kurum abonelikleri; koltuk başına planlar."},"edge":{"en":"Starts from workflows already in production for a related party; every number traceable to a document.","tr":"İlişkili taraf için üretimde olan iş akışlarından başlar; her rakam bir belgeye izlenebilir."},"brand":{"bg":"#F4F5F0","fg":"#10231C","accent":"#0E4A3A","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600","IBM+Plex+Mono:wght@400;500"],"extra":{"surface":"#FFFFFF","elevated":"#E8EDE6","border":"#D6DDD3","green":"#1FBF75","gold":"#8F6614","mono":"IBM Plex Mono"}},"links":[],"slug":"finans"},{"key":"medya","engine":"studio","kind":"app","frame":"browser","name":{"en":"Tamam Media (working name)","tr":"Tamam Media (çalışma adı)"},"stage":"idea","platforms":["Web"],"sectors":["media"],"tagline":{"en":"Content for every platform, and the rights to make it.","tr":"Her platform için içerik ve onu üretecek haklar."},"description":{"en":"The media and entertainment line, planned as its own subsidiary: AI-assisted production for YouTube, podcasts, original music, a short film and a series package with human editorial direction — and a rights business that licenses defined uses of a person's image and voice for the AI era, with a rights register, an approval workflow and royalties paid through to talent. Commissioned content first; documented permission only. December 2026 targets: a channel concept and three pilot videos, two podcast episodes and two music demos, a 3–5 minute short film, a series bible and teaser, and one signed pilot licence.","tr":"Kendi iştiraki olarak planlanan medya ve eğlence hattı: insan editöryel yönetimiyle YouTube, podcast, özgün müzik, kısa film ve dizi paketi için yapay zekâ destekli üretim — ve yapay zekâ çağı için bir kişinin görüntü ve sesinin tanımlı kullanımlarını lisanslayan, hak sicili, onay akışı ve sanatçıya aktarılan telifle çalışan bir haklar işi. Önce sipariş içerik; yalnızca belgeli izin. Aralık 2026 hedefleri: bir kanal konsepti ve üç pilot video, iki podcast bölümü ve iki müzik demosu, 3–5 dakikalık kısa film, dizi kitabı ve teaser, bir imzalı pilot lisans."},"user":{"en":"Publishers, brands and talent; audiences on every platform.","tr":"Yayıncılar, markalar ve sanatçılar; her platformdaki izleyici."},"aiCore":{"en":"Generation for script, storyboard, voice and video with licensed inputs; a consent-first rights register; editorial checks before every publish.","tr":"Lisanslı girdilerle senaryo, storyboard, ses ve video üretimi; izin odaklı hak sicili; her yayından önce editöryel kontrol."},"money":{"en":"Commissions, licence administration fees or negotiated commissions, production fees; channel revenue, format licensing and distribution after audience demand.","tr":"Sipariş, lisans yönetim ücreti ya da müzakere edilen komisyon, yapım ücreti; izleyici talebinden sonra kanal geliri, format lisansı ve dağıtım."},"edge":{"en":"Rights access plus production delivery in one place; a licensed voice marketplace already exists at ElevenLabs, so Tamam differentiates on rights and delivery.","tr":"Hak erişimi ve yapım teslimi tek yerde; lisanslı ses pazarı ElevenLabs'te zaten var, Tamam haklar ve teslimle ayrışır."},"brand":{"bg":"#0B0B0F","fg":"#F2F2F5","accent":"#FF2D75","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,600..800","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#14141B","elevated":"#1D1D27","border":"#2A2A38","amber":"#FFB443","muted":"#9A9AAE"}},"links":[]},{"key":"tryon","engine":"studio","kind":"app","frame":"phone","name":"Desen","stage":"live","platforms":["iOS","Android","Web"],"tagline":{"en":"Try the look on your own photo. Still you.","tr":"Yeni görünümü kendi fotoğrafında dene. Hâlâ sen."},"description":{"en":"A personal style studio for adults: outfits, tattoos, hair, makeup, headscarves, accessories and nails. The current app has a working sample-model flow with six pre-generated looks, a draggable before/after seam, saved looks, occasion planning and a colour guide. Live generation is held until the image provider and photo privacy conditions are ready.","tr":"Yetişkinler için kişisel görünüm stüdyosu: kıyafet, dövme, saç, makyaj, eşarp, aksesuar ve tırnak. Mevcut uygulamada örnek modelle altı hazır görünüm, kaydırılabilir önce/sonra çizgisi, kaydedilen görünümler, davet planı ve renk rehberi bulunuyor. Canlı üretim, görsel sağlayıcı ve fotoğraf gizliliği koşulları tamamlanınca açılacak."},"user":{"en":"Adults who screenshot outfits before buying or plan an event look, and first-tattoo planners deciding design, size and placement; tattoo studios and fashion retailers later (not yet validated).","tr":"Satın almadan önce kıyafetin ekran görüntüsünü alan ya da bir davet için görünüm planlayan yetişkinler ve tasarımı, boyutu ve yeri düşünen ilk dövme adayları; ileride dövme stüdyoları ve moda perakendecileri (henüz doğrulanmadı)."},"aiCore":{"en":"A server-side generation API, preset catalogue, moderation and quotas are implemented. The default preview uses local sample images; real provider access is not enabled.","tr":"Sunucu tarafında üretim API’si, hazır seçenekler, içerik kontrolü ve kota yapısı geliştirildi. Varsayılan önizleme yerel örnek görseller kullanıyor; gerçek görsel sağlayıcı henüz açık değil."},"money":{"en":"Freemium: a small monthly allowance of try-ons, then a monthly or yearly subscription plus credit packs, priced after the retention and conversion gates (every generation has an engine cost, so the free tier is sized against it). Labelled paid links on 'shop similar'; tattoo-studio seats and a retailer widget later. No advertising built on photo or face data.","tr":"Freemium: ayda küçük bir ücretsiz deneme hakkı, ardından aylık ya da yıllık abonelik ve kredi paketleri; fiyat tutunma ve dönüşüm kapılarından sonra belirlenir (her üretimin bir motor maliyeti var, ücretsiz kota buna göre ayarlanır). 'Benzerini bul' bölümünde etiketli ücretli bağlantılar; ileride dövme stüdyosu koltukları ve perakendeci widget'ı. Fotoğraf ya da yüz verisine dayalı reklam yok."},"edge":{"en":"One private studio for clothing, ink and beauty, with no face recognition or ad tracking. Every AI result is labelled.","tr":"Kıyafet, dövme ve güzellik için tek bir mahrem stüdyo. Yüz tanıma ve reklam takibi yok; her yapay zekâ sonucu etiketleniyor."},"brand":{"bg":"#F2EDE6","fg":"#15131A","accent":"#3A4BFF","fontDisplay":"Bodoni Moda","fontBody":"Instrument Sans","fontsCss2":["Bodoni+Moda:opsz,wght@6..96,500..800","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#FFFFFF","line":"#E0D9CF","muted":"#6B6560","cobalt":"#3A4BFF"}},"links":[],"slug":"desen","sectors":["lifestyle"],"phase":1},{"key":"home","engine":"studio","kind":"app","frame":"phone","name":"Decorum","stage":"live","platforms":["iOS","Android"],"tagline":{"en":"Photograph your space. See a new possibility.","tr":"Mekânını çek. Yeni hâlini gör."},"description":{"en":"An Expo phone app for restyling a corner, living room, kitchen, bedroom, entry or garden against a budget. A user can choose or take a room photo, compare illustrated looks, pick taste cards and save a plan. When configured, a Supabase function can request a live restyle; the local illustration remains as a fallback. Product lists and prices are illustrative and retailers are not connected.","tr":"Bir köşeyi, salonu, mutfağı, yatak odasını, girişi ya da bahçeyi bütçeye göre yeniden tasarlayan Expo telefon uygulaması. Kullanıcı oda fotoğrafı seçebilir ya da çekebilir, örnek görünümleri karşılaştırabilir, zevk kartları seçebilir ve planını kaydedebilir. Kurulduğunda Supabase işlevi canlı düzenleme isteyebilir; olmazsa yerel örnek çizim kalır. Ürün listeleri ve fiyatlar temsili, mağazalar bağlı değil."},"user":{"en":"Renters and first-home movers who save decor posts and refresh one corner at a time; in Türkiye also new-home and çeyiz shoppers and students furnishing a first flat (hypotheses to test). Retailers and listing owners later.","tr":"Dekorasyon gönderisi kaydeden ve evini köşe köşe yenileyen kiracılar ve ilk evine taşınanlar; Türkiye'de ayrıca yeni ev ve çeyiz alışverişi yapanlar ve ilk evini döşeyen öğrenciler (test edilecek varsayımlar). İleride perakendeciler ve ilan sahipleri."},"aiCore":{"en":"A configured Supabase function sends room photos for a restyle; on-device illustrations and sample spaces support the preview. Retail matching is future work.","tr":"Yapılandırılmış Supabase işlevi oda fotoğrafını yeniden tasarım için gönderir; uygulamadaki örnek çizimler ve mekânlar önizlemeyi destekler. Mağaza eşleştirmesi sonraki aşamada."},"money":{"en":"Freemium: a few free proposals each month, then a subscription for unlimited rooms, whole-home boards and high-resolution export, priced after the retention and conversion gates. Labelled paid links on shoppable items once retailer deals exist (counted as zero until then); disclosed sponsored slots and labelled virtual staging for Değer listings later.","tr":"Freemium: ayda birkaç ücretsiz öneri, ardından sınırsız oda, tüm ev panoları ve yüksek çözünürlüklü dışa aktarım için abonelik; fiyat tutunma ve dönüşüm kapılarından sonra belirlenir. Perakendecilerle anlaşma olunca satın alınabilir parçalarda etiketli ücretli bağlantılar (o zamana kadar sıfır sayılır); ileride açıkça belirtilen sponsorlu alanlar ve Değer ilanları için etiketli sanal döşeme."},"edge":{"en":"Room and corner scale concepts across six spaces, with budget and taste controls already visible in the app.","tr":"Altı mekân türünde oda ve köşe ölçeğinde fikirler; bütçe ve zevk seçimleri uygulamada mevcut."},"brand":{"bg":"#F1EBE2","fg":"#231D18","accent":"#566628","fontDisplay":"Fraunces","fontBody":"Instrument Sans","fontsCss2":["Fraunces:opsz,wght@9..144,400..700","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#FBF8F3","line":"#DDD3C4","ink2":"#5C5148","walnut":"#7A5234","linen":"#E6DCCD","clay":"#B0572F","paid":"#7E5F14"}},"links":[],"slug":"decorum","sectors":["lifestyle","marketplace"],"phase":1},{"key":"rights","engine":"studio","kind":"web","frame":"browser","name":{"en":"Cachet (working name)","tr":"Cachet (çalışma adı)"},"stage":"idea","platforms":[{"en":"Web platform","tr":"Web platformu"},{"en":"Mobile approval for talent","tr":"Sanatçı için mobil onay"}],"tagline":{"en":"Licensed voice and likeness, with the talent's signature on every use.","tr":"Lisanslı ses ve görüntü; her kullanımda sanatçının imzasıyla."},"description":{"en":"Talent rights for the AI era. Cachet signs actors, voice artists, musicians and creators, records written consent for each purpose, builds a scope-locked digital twin of their voice and face from their own recordings, and licenses defined uses to brands, studios, game makers and publishers. Every licence names the use, media, territory and term; every output carries a watermark and Content Credentials; a monitor finds unlicensed copies and files takedowns; royalties reach the talent on a statement every period. A sister line to Tamam Media inside the planned Media & Entertainment subsidiary: Cachet clears and licenses the rights, Tamam Media produces the content. Documented permission only.","tr":"Yapay zekâ çağı için sanatçı hakları. Cachet oyuncular, seslendirme sanatçıları, müzisyenler ve içerik üreticileriyle anlaşır, her amaç için yazılı izni kayda alır, ses ve yüzlerinin kendi kayıtlarından kurulan, kapsamı kilitli dijital ikizini oluşturur ve tanımlı kullanımları markalara, stüdyolara, oyun yapımcılarına ve yayıncılara lisanslar. Her lisans kullanımı, mecrayı, bölgeyi ve süreyi belirtir; her çıktı filigran ve İçerik Kimlik Bilgileri taşır; izleme modülü lisanssız kopyaları bulup kaldırma talebi açar; telif her dönem bir ekstreyle sanatçıya ulaşır. Planlanan Medya ve Eğlence iştiraki içinde Tamam Media'nın kardeş hattı: hakları Cachet temizler ve lisanslar, içeriği Tamam Media üretir. Yalnızca belgeli izinle."},"user":{"en":"Talent, their agents and estates; brands, agencies, studios, game and app makers that need a licensed voice or face — starting with Turkish-language talent.","tr":"Sanatçılar, menajerleri ve mirasçıları; lisanslı bir ses ya da yüze ihtiyaç duyan markalar, ajanslar, stüdyolar, oyun ve uygulama yapımcıları — önce Türkçe konuşan sanatçılarla."},"aiCore":{"en":"Voice and face models built only from the talent's own recordings under written consent, with generation locked to an active licence ID and scope checks before every call; AudioSeal-style audio watermarks and C2PA manifests with an AI-disclosure assertion; face and voice matching to find unlicensed copies, with human review for parody and news. Tamam's own IP is the consent vault, licence engine, monitor and royalty ledger, not a frontier voice model.","tr":"Yalnızca yazılı izinle, sanatçının kendi kayıtlarından kurulan ses ve yüz modelleri; üretim etkin bir lisans numarasına kilitli, her çağrıdan önce kapsam denetimi; AudioSeal tarzı ses filigranı ve yapay zekâ beyanı içeren C2PA kayıtları; lisanssız kopyaları bulmak için yüz ve ses eşleştirme, parodi ve haber için insan incelemesi. Tamam'ın kendi fikri mülkiyeti öncü bir ses modeli değil; izin kasası, lisans motoru, izleme ve telif defteridir."},"money":{"en":"Licence fees per defined use (use type × media × territory × term × exclusivity); minimum guarantees recoupable against usage royalties for ongoing uses; an agency commission on each licence, with the rest paid through to the talent; a protection subscription for talent; capture and production fees when Tamam Media makes the content.","tr":"Tanımlı kullanım başına lisans ücreti (kullanım türü × mecra × bölge × süre × münhasırlık); sürekli kullanımlarda kullanım telifinden mahsup edilen asgari garanti; her lisanstan ajans komisyonu, kalanı sanatçıya aktarılır; sanatçılar için koruma aboneliği; içeriği Tamam Media ürettiğinde kayıt ve yapım ücreti."},"edge":{"en":"One desk for signing, consent, licensing, provenance, monitoring and royalties, starting with Turkish-language talent — a combination we did not find in Türkiye (Sept 2026 review, not exhaustive). ElevenLabs runs a licensed voice marketplace and Loti and Vermillio sell monitoring; Cachet differentiates on the whole chain, Turkish paperwork and production delivery through Tamam Media.","tr":"İmza, izin, lisans, köken, izleme ve telif tek masada; önce Türkçe konuşan sanatçılarla — Türkiye'de bu bileşimi bulamadık (Eylül 2026 incelemesi, kapsamlı değil). Lisanslı ses pazarını ElevenLabs, izleme hizmetini Loti ve Vermillio sunuyor; Cachet tüm zincir, Türkçe hukuki evrak ve Tamam Media üzerinden yapım teslimiyle ayrışır."},"brand":{"bg":"#111013","fg":"#F1ECE2","accent":"#E2553F","fontDisplay":"Instrument Serif","fontBody":"Instrument Sans","fontsCss2":["Instrument+Serif:ital@0;1","Instrument+Sans:wght@400;500;600"],"extra":{"surface":"#1A191D","elevated":"#232228","line":"#2F2D34","muted":"#9C968C","ok":"#3FBF7F","warn":"#E3A93B","seal":"#B8322A","mono":"IBM Plex Mono"}},"links":[],"slug":"cachet","sectors":["media","legal"]},{"key":"marketing","engine":"agents","kind":"agent","frame":"browser","name":{"en":"Terazi (working name)","tr":"Terazi (çalışma adı)"},"stage":"live","platforms":[{"en":"Web dashboard","tr":"Web panosu"},{"en":"Ad-network and MMP connectors","tr":"Reklam ağı ve MMP bağlantıları"},{"en":"Weekly gate review","tr":"Haftalık kapı incelemesi"}],"tagline":{"en":"Spend on one pan, revenue on the other — by channel and cohort.","tr":"Bir kefede harcama, öbüründe gelir — kanal kanal, kohort kohort."},"description":{"en":"The studio's marketing analytics desk. It joins spend from Meta, Google Ads, TikTok, Apple Ads and influencer deals to installs, trials, subscriptions and refunds; shows CPI, CAC, ROAS by day, predicted LTV and payback by channel, campaign and cohort; tracks budget pacing against plan; and writes AI recommendations that a person approves before any budget moves. It grows out of the studio's existing spend-and-return dashboard, runs the three gates on every Tamam app first, then goes to other app publishers and D2C brands.","tr":"Stüdyonun pazarlama analitiği masası. Meta, Google Ads, TikTok, Apple Ads ve influencer anlaşmalarındaki harcamayı kurulum, deneme, abonelik ve iadelerle birleştirir; kanal, kampanya ve kohort bazında CPI, CAC, günlere göre ROAS, tahmini LTV ve geri ödeme süresini gösterir; bütçe temposunu planla karşılaştırır ve bütçe oynamadan önce bir kişinin onayladığı yapay zekâ önerileri yazar. Stüdyonun mevcut harcama ve getiri panosundan büyür; önce her Tamam uygulamasında üç kapıyı ölçer, sonra diğer uygulama yayıncılarına ve D2C markalarına açılır."},"user":{"en":"Growth teams at app studios and D2C brands; first, Tamam's own app owners and the weekly gate review.","tr":"Uygulama stüdyoları ve D2C markalarının büyüme ekipleri; önce Tamam'ın kendi uygulama sahipleri ve haftalık kapı incelemesi."},"aiCore":{"en":"Every metric is a SQL view (CPI, CAC, ROAS D0–D180, LTV, payback, pacing, gate status) and the model never computes a number; cohort revenue forecasts with confidence bands, saturation curves for marginal ROAS, anomaly detection (broken tracking, CPI and refund spikes); Claude writes recommendations over the computed numbers, each linked to its evidence and waiting for approval. Lift tests first; open-source MMM (Meridian or Robyn) once the spend history allows.","tr":"Her metrik bir SQL görünümüdür (CPI, CAC, ROAS D0–D180, LTV, geri ödeme, tempo, kapı durumu) ve model hiçbir rakamı kendisi hesaplamaz; güven aralıklı kohort gelir tahmini, marjinal ROAS için doygunluk eğrileri, anomali tespiti (kırılan izleme, CPI ve iade sıçramaları); Claude hesaplanmış rakamlar üzerine öneriler yazar, her biri kanıtına bağlıdır ve onay bekler. Önce kaldırma (lift) testleri; harcama geçmişi yettiğinde açık kaynak MMM (Meridian ya da Robyn)."},"money":{"en":"Internal first. Then a setup fee plus a monthly subscription for publishers and brands, bundled with orchestration and consulting work; pricing after paid pilots.","tr":"Önce iç kullanım. Sonra yayıncı ve markalara kurulum ücreti artı aylık abonelik, orkestrasyon ve danışmanlık işleriyle paket; fiyat ücretli pilotlardan sonra."},"edge":{"en":"The same instrument the studio uses to decide which apps to scale: cohort returns with predicted payback, the kind of in-house marketing analytics large app studios keep to themselves, sold here as a service. Recommendations never move budget on their own, and every number traces to a SQL view.","tr":"Stüdyonun hangi uygulamayı büyüteceğine karar verdiği aynı araç: tahmini geri ödemeli kohort getirisi; büyük uygulama stüdyolarının kendine sakladığı türden bir iç pazarlama analitiği, burada hizmet olarak satılıyor. Öneriler bütçeyi asla kendiliğinden oynatmaz; her rakam bir SQL görünümüne izlenir."},"brand":{"bg":"#F6F6F3","fg":"#11161C","accent":"#0B6E77","fontDisplay":"Bricolage Grotesque","fontBody":"Instrument Sans","fontsCss2":["Bricolage+Grotesque:opsz,wght@12..96,500..800","Instrument+Sans:wght@400;500;600","IBM+Plex+Mono:wght@400;500"],"extra":{"surface":"#FFFFFF","line":"#DEE2E3","muted":"#5E6870","spend":"#C4461F","return":"#12774F","watch":"#9A6412","fail":"#B83A3A","mono":"IBM Plex Mono"}},"links":[],"slug":"terazi","sectors":["marketing"],"phase":1},{"key":"steward","engine":"studio","kind":"web","frame":"browser","name":"AI Steward","stage":"idea","platforms":[{"en":"Desktop control plane","tr":"Masaüstü kontrol paneli"},{"en":"Laptop agent concept","tr":"Dizüstü ajanı fikri"}],"sectors":["enterprise","analytics"],"tagline":{"en":"The AI credit meter for companies.","tr":"Şirketler için yapay zekâ kredi sayacı."},"description":{"en":"AI Steward is a concept for showing company leaders where AI credits go, by person, project and purpose. The proposed light agent on each company laptop records AI sessions; a server compiles monthly reports for colleagues, managers and leadership. The shared film and design brief explain the concept; the product is not yet in development.","tr":"AI Steward, şirket yöneticilerine yapay zekâ kredilerinin kişi, proje ve kullanım amacı bazında nereye gittiğini göstermeyi amaçlayan bir fikir. Önerilen hafif dizüstü ajanı oturumları kaydeder; sunucu çalışan, yönetici ve üst yönetim için aylık raporlar hazırlar. Paylaşılan film ve tasarım dosyası fikri anlatır; ürün henüz geliştirme aşamasında değildir."},"user":{"en":"Company leaders, finance and IT teams responsible for AI-tool spending and adoption.","tr":"Yapay zekâ araçlarının harcama ve kullanımını yöneten şirket liderleri, finans ve BT ekipleri."},"aiCore":{"en":"Planned laptop-side collection linked to a person, project and purpose, with server-side aggregation and reporting.","tr":"Kişi, proje ve kullanım amacına bağlanan dizüstü veri toplama ve sunucu tarafında birleştirilmiş raporlama planı."},"money":{"en":"Commercial model has not been defined; this is an idea-stage product brief.","tr":"Ticari model henüz belirlenmedi; bu fikir aşamasında bir ürün taslağıdır."},"edge":{"en":"A credit-level view of AI use tied to the work it supports, with monthly reports at colleague, manager and leadership levels.","tr":"Yapay zekâ kullanımını desteklediği işle birlikte kredi düzeyinde gösteren; çalışan, yönetici ve üst yönetim için aylık rapor taslağı."},"brand":{"bg":"#060B17","fg":"#F4EFE3","accent":"#D8B262","fontDisplay":"Fraunces","fontBody":"Inter","fontsCss2":["Fraunces:opsz,wght@9..144,300..600","Inter:wght@400;500;600"],"extra":{"navy":"#0A1428","gold2":"#F1D592","muted":"#AEB7CB"}},"links":[],"slug":"ai-steward"}]};
